RKfill("pgdba",[{"b":["<b>PostgreSQL</b> adalah database relasional open source yang dikembangkan sejak 1986. Ia dikenal patuh standar SQL, andal (ACID), dan mudah diperluas: tipe data JSONB, pencarian teks penuh, PostGIS untuk peta, dan pgvector untuk AI. Gojek, Tokopedia, Instagram, dan banyak startup memakainya.","<b>Database Administrator (DBA)</b> memastikan database aman, cepat, dan tidak kehilangan data. Tugas hariannya: membuat dan mengatur pengguna serta hak akses, memantau performa, menyetel konfigurasi, membuat indeks, menjadwalkan backup, menguji pemulihan, menyiapkan replikasi, dan meningkatkan versi.","Jalur ini mengikuti peta belajar PostgreSQL DBA. Kamu perlu dasar SQL (SELECT, JOIN, GROUP BY) dulu; jika belum, selesaikan jalur SQL di Ruang Kode."],"lang":"sql","code":"-- versi server dan waktu sekarang\nSELECT version();\nSELECT current_database(), current_user, now()::date;","out":" PostgreSQL 17.2 on x86_64-pc-linux-gnu, compiled by gcc 12.2.0, 64-bit\n\n current_database | current_user |    now\n------------------+--------------+------------\n tokodb           | postgres     | 2026-11-05","run":false,"tb":[{"c":"Tanggung jawab DBA","h":["Area","Contoh pekerjaan"],"r":[["Keamanan","Role, GRANT, pg_hba.conf, SSL, audit"],["Performa","EXPLAIN, indeks, konfigurasi memori, connection pooling"],["Ketersediaan","Replikasi, failover, high availability"],["Pemulihan","pg_dump, pg_basebackup, PITR, uji restore"],["Perawatan","VACUUM, ANALYZE, upgrade versi, bloat"],["Pemantauan","pg_stat_*, log, Prometheus, Grafana"]]}],"pts":["PostgreSQL: relasional, open source, ACID, mudah diperluas.","DBA menjaga keamanan, performa, ketersediaan, dan data.","Butuh dasar SQL sebelum masuk jalur ini."],"q":[["Tugas mana yang termasuk pekerjaan DBA?",["Menguji pemulihan backup","Mendesain logo","Menulis CSS"],0,"Backup tanpa uji restore belum tentu bisa dipakai."]],"deep":{"ist":[["DBA (Database Administrator)","Penanggung jawab ketersediaan, kinerja, keamanan, dan keutuhan data di database."],["RPO / RTO","Recovery Point Objective (berapa banyak data boleh hilang) dan Recovery Time Objective (berapa lama boleh mati)."],["SLA / SLO","Janji layanan ke pengguna, misalnya ketersediaan 99,95% per bulan (sekitar 22 menit downtime)."],["Runbook","Prosedur tertulis langkah demi langkah untuk operasi rutin dan insiden (failover, restore)."],["Managed database","Layanan cloud seperti Amazon RDS/Aurora, Cloud SQL, Azure Flexible Server; DBA tetap mengurus skema, query, dan akses."]],"cx":[{"t":"Mengenal server: versi, ukuran database, dan pengaturan penting","b":"Pertanyaan pertama DBA saat memegang server baru: versi berapa, seberapa besar, dan bagaimana konfigurasinya.","code":"SELECT current_setting('server_version') AS versi, current_database() AS db,\n       pg_size_pretty(pg_database_size(current_database())) AS ukuran;\nSELECT name, setting, unit, short_desc\nFROM pg_settings\nWHERE lower(name) IN ('max_connections', 'shared_buffers', 'work_mem', 'wal_level', 'timezone')\nORDER BY name;","lang":"sql","out":"                 versi                 |    db    | ukuran\n---------------------------------------+----------+---------\n 16.15 (Ubuntu 16.15-0ubuntu0.24.04.1) | contoh_1 | 7567 kB\n(1 row)\n\n      name       |   setting    | unit |                           short_desc\n-----------------+--------------+------+-----------------------------------------------------------------\n TimeZone        | Asia/Jakarta |      | Sets the time zone for displaying and interpreting time stamps.\n max_connections | 100          |      | Sets the maximum number of concurrent connections.\n shared_buffers  | 16384        | 8kB  | Sets the number of shared memory buffers used by the server.\n wal_level       | replica      |      | Sets the level of information written to the WAL.\n work_mem        | 4096         | kB   | Sets the maximum memory to be used for query workspaces.\n(5 rows)"},{"t":"Menghitung anggaran downtime dari SLA","code":"SLA 99,9%   -> 43 menit 49 detik per bulan\nSLA 99,95%  -> 21 menit 54 detik per bulan\nSLA 99,99%  ->  4 menit 22 detik per bulan\nArtinya: dengan 99,95%, satu kali restore 30 menit sudah melanggar SLA,\nsehingga perlu replika siaga (failover < 1 menit), bukan hanya backup.","lang":"text"}]}},{"b":["PostgreSQL memakai model <b>satu proses per koneksi</b>. Proses induk <code>postmaster</code> menerima koneksi lalu membuat proses <b>backend</b> untuk setiap klien. Karena itu ribuan koneksi langsung memboroskan memori; solusinya <b>connection pooler</b> seperti PgBouncer.","Proses latar belakang penting: <b>checkpointer</b> (menulis halaman kotor ke disk secara berkala), <b>background writer</b>, <b>WAL writer</b>, <b>autovacuum launcher</b>, dan <b>walsender</b> untuk replikasi. Memori bersama utama adalah <code>shared_buffers</code>, cache halaman data berukuran 8 kB.","Setiap perubahan ditulis dulu ke <b>WAL</b> (Write-Ahead Log) sebelum ke file data. Jika server mati mendadak, PostgreSQL memutar ulang WAL sejak checkpoint terakhir. WAL juga menjadi dasar replikasi dan point-in-time recovery. Data tersimpan di direktori <code>PGDATA</code>: <code>base/</code> untuk tabel, <code>pg_wal/</code> untuk WAL."],"lang":"sql","code":"-- proses yang sedang berjalan\nSELECT pid, backend_type, state\nFROM pg_stat_activity\nORDER BY backend_type;\n\nSHOW data_directory;\nSHOW shared_buffers;","out":"  pid  |         backend_type         | state\n-------+------------------------------+--------\n    61 | autovacuum launcher          |\n    59 | background writer            |\n    58 | checkpointer                 |\n   312 | client backend               | active\n    62 | logical replication launcher |\n    60 | walwriter                    |\n\n     data_directory\n--------------------------\n /var/lib/postgresql/data\n\n shared_buffers\n----------------\n 128MB","run":false,"pts":["Satu proses backend per koneksi, pakai pooler untuk banyak koneksi.","WAL ditulis sebelum file data: kunci pemulihan dan replikasi.","shared_buffers adalah cache halaman data."],"q":[["Kenapa PostgreSQL bisa pulih setelah listrik padam?",["Perubahan sudah tercatat di WAL","Data selalu di RAM","Karena autovacuum"],0,"WAL diputar ulang sejak checkpoint."],["Solusi untuk 3.000 koneksi aplikasi?",["Connection pooler seperti PgBouncer","Menaikkan max_connections ke 3000","Mematikan autovacuum"],0,"Setiap koneksi adalah proses."]],"deep":{"ist":[["Postmaster","Proses induk PostgreSQL yang menerima koneksi dan membuat satu backend process per koneksi."],["Shared buffers","Cache halaman data (8 KB) di memori bersama; umumnya 25% RAM sebagai titik awal."],["WAL (Write-Ahead Log)","Log perubahan yang ditulis sebelum data; dasar crash recovery, replikasi, dan PITR."],["Checkpoint","Saat halaman kotor di memori ditulis ke disk sehingga WAL lama bisa didaur ulang."],["Background worker","Proses pendukung: checkpointer, background writer, WAL writer, autovacuum launcher."]],"cx":[{"t":"Melihat proses yang berjalan dan lokasi fisik sebuah tabel","b":"Setiap tabel adalah berkas di direktori base/<oid database>/; datanya tersusun dalam halaman 8 KB.","code":"SELECT backend_type, count(*) FROM pg_stat_activity GROUP BY 1 ORDER BY 1;\n\nCREATE TABLE contoh (id int);\nINSERT INTO contoh SELECT generate_series(1, 100000);\nSELECT pg_relation_filepath('contoh') AS file_di_disk,\n       pg_size_pretty(pg_relation_size('contoh')) AS ukuran,\n       pg_relation_size('contoh') / current_setting('block_size')::int AS jumlah_halaman_8kb;","lang":"sql","out":"         backend_type         | count\n------------------------------+-------\n autovacuum launcher          |     1\n background writer            |     1\n checkpointer                 |     1\n client backend               |     1\n logical replication launcher |     1\n walwriter                    |     1\n(6 rows)\n\n   file_di_disk   | ukuran  | jumlah_halaman_8kb\n------------------+---------+--------------------\n base/18122/18123 | 3544 kB |                443\n(1 row)"},{"t":"WAL bertambah setiap kali data berubah","b":"LSN (Log Sequence Number) adalah posisi di WAL. Selisih LSN dipakai juga untuk mengukur lag replikasi.","code":"SELECT pg_current_wal_lsn() AS lsn_awal \\gset\nCREATE TABLE log_uji AS SELECT g AS id, md5(g::text) AS isi FROM generate_series(1, 50000) g;\nSELECT pg_size_pretty(pg_wal_lsn_diff(pg_current_wal_lsn(), :'lsn_awal')) AS wal_dihasilkan;","lang":"sql","out":" wal_dihasilkan\n----------------\n 4712 kB\n(1 row)"}]}},{"b":["Cara tercepat mencoba PostgreSQL adalah <b>Docker</b>. Di server produksi, pasang dari repositori resmi (apt.postgresql.org untuk Ubuntu) atau pakai layanan terkelola seperti Amazon RDS, Google Cloud SQL, atau Supabase.","<b>psql</b> adalah klien baris perintah resmi. Perintah meta diawali garis miring terbalik: <code>\\l</code> daftar database, <code>\\c nama</code> pindah database, <code>\\dt</code> daftar tabel, <code>\\d tabel</code> struktur tabel, <code>\\du</code> daftar role, <code>\\x</code> tampilan vertikal, <code>\\timing</code> menampilkan durasi query, dan <code>\\q</code> keluar.","Simpan data di <b>volume</b> agar tidak hilang saat container dihapus, dan jangan pernah memakai kata sandi contoh di produksi."],"lang":"bash","code":"docker run -d --name pg17 \\\n  -e POSTGRES_PASSWORD=rahasia_kuat \\\n  -v pgdata:/var/lib/postgresql/data \\\n  -p 5432:5432 postgres:17\n\ndocker exec -it pg17 psql -U postgres\n\npostgres=# CREATE DATABASE tokodb;\npostgres=# \\c tokodb\ntokodb=# \\timing on\ntokodb=# \\dt","out":"CREATE DATABASE\nYou are now connected to database \"tokodb\" as user \"postgres\".\nTiming is on.\nDid not find any relations.","run":false,"tb":[{"c":"Perintah meta psql","h":["Perintah","Fungsi"],"r":[["\\l","Daftar database"],["\\c db","Pindah database"],["\\dt","Daftar tabel"],["\\d tabel","Kolom, indeks, constraint"],["\\du","Daftar role"],["\\dn","Daftar schema"],["\\x","Tampilan vertikal"],["\\timing","Tampilkan durasi query"],["\\i file.sql","Jalankan file"],["\\q","Keluar"]]}],"so":[{"q":"Tulis perintah psql untuk menghubungkan ke database <code>tokodb</code> di host 10.0.0.5 sebagai user <code>analis</code>.","h":"Opsi -h host, -U user, -d database.","a":"psql -h 10.0.0.5 -U analis -d tokodb","lang":"sql"}],"pts":["Docker untuk belajar, paket resmi atau layanan terkelola untuk produksi.","Simpan data di volume.","Hafalkan \\l, \\c, \\dt, \\d, \\du."],"q":[["Perintah psql untuk melihat struktur tabel produk?",["\\d produk","\\l produk","SHOW produk"],0,"\\d menampilkan kolom, indeks, dan constraint."]],"deep":{"ist":[["psql","Klien baris perintah resmi PostgreSQL; meta-command diawali backslash (\\dt, \\d+, \\x, \\timing)."],["Volume","Penyimpanan Docker di luar container agar data tidak hilang saat container dihapus."],["PGDATA","Direktori data cluster PostgreSQL berisi berkas tabel, WAL, dan konfigurasi."],["Connection string","Alamat koneksi seperti postgresql://user:sandi@host:5432/db?sslmode=require."],[".pgpass / service file","Cara menyimpan kredensial koneksi tanpa menulis password di perintah atau skrip."]],"cx":[{"t":"docker compose untuk PostgreSQL 16 + pgAdmin","code":"# compose.yaml\nservices:\n  db:\n    image: postgres:16\n    environment:\n      POSTGRES_USER: admin\n      POSTGRES_PASSWORD_FILE: /run/secrets/pg_sandi     # jangan tulis password langsung di file\n      POSTGRES_DB: toko\n      TZ: Asia/Jakarta\n    ports: [\"127.0.0.1:5432:5432\"]                       # hanya bisa diakses dari mesin sendiri\n    volumes:\n      - pgdata:/var/lib/postgresql/data\n      - ./init:/docker-entrypoint-initdb.d               # skrip .sql dijalankan saat pertama dibuat\n    healthcheck:\n      test: [\"CMD-SHELL\", \"pg_isready -U admin -d toko\"]\n      interval: 5s\n    secrets: [pg_sandi]\nvolumes: { pgdata: {} }\nsecrets: { pg_sandi: { file: ./pg_sandi.txt } }\n\n# docker compose up -d && docker compose exec db psql -U admin -d toko","lang":"yaml"},{"t":"Meta-command psql yang paling sering dipakai DBA","b":"\\d menampilkan struktur tabel lengkap dengan indeks dan constraint; \\x on mengubah tampilan menjadi vertikal untuk baris yang lebar.","code":"CREATE TABLE produk (id serial PRIMARY KEY, nama text NOT NULL, harga numeric(12,0) CHECK (harga > 0));\nCREATE INDEX ON produk (nama);\n\\d produk\n\\dt\n\\x on\nSELECT name, setting, unit, context, source, short_desc FROM pg_settings WHERE name = 'work_mem';","lang":"sql","out":"                               Table \"public.produk\"\n Column |     Type      | Collation | Nullable |              Default\n--------+---------------+-----------+----------+------------------------------------\n id     | integer       |           | not null | nextval('produk_id_seq'::regclass)\n nama   | text          |           | not null |\n harga  | numeric(12,0) |           |          |\nIndexes:\n    \"produk_pkey\" PRIMARY KEY, btree (id)\n    \"produk_nama_idx\" btree (nama)\nCheck constraints:\n    \"produk_harga_check\" CHECK (harga > 0::numeric)\n\n         List of relations\n Schema |  Name  | Type  |  Owner\n--------+--------+-------+----------\n public | produk | table | postgres\n(1 row)\n\n-[ RECORD 1 ]--------------------------------------------------------\nname       | work_mem\nsetting    | 4096\nunit       | kB\ncontext    | user\nsource     | default\nshort_desc | Sets the maximum memory to be used for query workspaces."}]}},{"b":["Hierarki objek PostgreSQL: <b>cluster</b> (satu server) berisi beberapa <b>database</b>, setiap database berisi <b>schema</b>, dan schema berisi tabel, view, fungsi, dan sequence. Query tidak bisa langsung JOIN antar database, tetapi bisa antar schema.","Schema bawaan bernama <code>public</code>. Pakai schema untuk memisahkan domain (<code>penjualan</code>, <code>gudang</code>) atau penyewa (multi-tenant). <code>search_path</code> menentukan schema mana yang dicari jika nama tabel ditulis tanpa awalan.","Untuk kunci utama, gunakan <code>GENERATED ALWAYS AS IDENTITY</code> (standar SQL) daripada <code>SERIAL</code> lama."],"lang":"sql","code":"CREATE SCHEMA penjualan;\n\nCREATE TABLE penjualan.pelanggan (\n  id        bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,\n  nama      text NOT NULL,\n  email     text UNIQUE,\n  kota      text DEFAULT 'Medan',\n  dibuat    timestamptz NOT NULL DEFAULT now()\n);\n\nINSERT INTO penjualan.pelanggan (nama, email)\nVALUES ('Rina', 'rina@contoh.id'), ('Budi', 'budi@contoh.id')\nRETURNING id, nama, kota;","out":"CREATE SCHEMA\nCREATE TABLE\n id | nama | kota\n----+------+------\n  1 | Rina | Medan\n  2 | Budi | Medan\n(2 rows)\n\nINSERT 0 2","run":false,"so":[{"q":"Buat schema <code>gudang</code> dan tabel <code>gudang.stok</code> dengan kolom id (identity), produk (teks wajib), jumlah (bilangan bulat default 0).","h":"CREATE SCHEMA lalu CREATE TABLE dengan awalan schema.","a":"CREATE SCHEMA gudang;\nCREATE TABLE gudang.stok (\n  id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,\n  produk text NOT NULL,\n  jumlah integer NOT NULL DEFAULT 0\n);","lang":"sql"}],"pts":["Cluster → database → schema → tabel.","Schema memisahkan domain atau penyewa.","IDENTITY lebih disarankan daripada SERIAL."],"q":[["Bisakah satu query JOIN tabel di dua database berbeda secara langsung?",["Tidak, perlu extension seperti postgres_fdw","Bisa dengan titik","Bisa jika nama tabel sama"],0,"Antar schema bisa, antar database tidak."]],"deep":{"ist":[["Cluster","Satu instance PostgreSQL berisi banyak database; role berlaku di seluruh cluster."],["Schema","Namespace di dalam database (public, sales, audit) untuk mengelompokkan objek dan hak akses."],["search_path","Urutan schema yang dicari saat nama objek ditulis tanpa awalan schema."],["Identity column","Kolom auto-increment standar SQL (GENERATED ALWAYS AS IDENTITY), pengganti serial."],["Migration","Perubahan skema berversi yang dijalankan berurutan dengan alat seperti Flyway, Liquibase, sqitch, atau Alembic."]],"cx":[{"t":"Memisahkan domain dengan schema dan search_path","code":"CREATE SCHEMA sales;\nCREATE SCHEMA audit;\nCREATE TABLE sales.pesanan (id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY, total numeric(14,0) NOT NULL);\nCREATE TABLE audit.log (id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY, aksi text, waktu timestamptz DEFAULT now());\n\nSET search_path = sales, public;\nINSERT INTO pesanan (total) VALUES (125000), (98000);\nSELECT * FROM pesanan;                      -- ditemukan di schema sales\n\nSELECT table_schema, table_name FROM information_schema.tables\nWHERE table_schema IN ('sales', 'audit') ORDER BY 1, 2;","lang":"sql","out":" id | total\n----+--------\n  1 | 125000\n  2 |  98000\n(2 rows)\n\n table_schema | table_name\n--------------+------------\n audit        | log\n sales        | pesanan\n(2 rows)"}]}},{"b":["Pilih tipe yang tepat: <code>integer</code> atau <code>bigint</code> untuk angka bulat, <code>numeric(12,2)</code> untuk uang (jangan <code>float</code>, karena tidak presisi), <code>text</code> untuk teks (sama cepatnya dengan varchar), <code>timestamptz</code> untuk waktu (selalu simpan zona waktu), <code>boolean</code>, <code>uuid</code>, <code>jsonb</code>, dan array seperti <code>text[]</code>.","<b>Constraint</b> menjaga data tetap benar di level database: <code>NOT NULL</code>, <code>UNIQUE</code>, <code>PRIMARY KEY</code>, <code>FOREIGN KEY</code> (dengan <code>ON DELETE CASCADE</code> atau <code>RESTRICT</code>), <code>CHECK</code> (misalnya harga harus positif), dan <code>EXCLUDE</code> (misalnya jadwal ruangan tidak boleh tumpang tindih).","Aturan bisnis di aplikasi bisa dilewati oleh skrip atau integrasi lain; constraint di database tidak bisa. Itu sebabnya DBA menyukai constraint."],"lang":"sql","code":"CREATE TABLE produk (\n  id     bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,\n  nama   text NOT NULL,\n  harga  numeric(12,2) NOT NULL CHECK (harga > 0),\n  tag    text[] DEFAULT '{}'\n);\n\nCREATE TABLE pesanan (\n  id         bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,\n  produk_id  bigint NOT NULL REFERENCES produk(id) ON DELETE RESTRICT,\n  jumlah     integer NOT NULL CHECK (jumlah BETWEEN 1 AND 100)\n);\n\nINSERT INTO produk (nama, harga) VALUES ('Kopi Gayo', -5000);","out":"CREATE TABLE\nCREATE TABLE\nERROR:  new row for relation \"produk\" violates check constraint \"produk_harga_check\"\nDETAIL:  Failing row contains (1, Kopi Gayo, -5000.00, {}).","run":false,"tb":[{"c":"Pilihan tipe data","h":["Kebutuhan","Tipe","Hindari"],"r":[["Uang","numeric(12,2)","float, real, money"],["Waktu kejadian","timestamptz","timestamp tanpa zona"],["Teks","text","char(n)"],["ID publik","uuid","angka berurutan yang mudah ditebak"],["Data semi-terstruktur","jsonb","json (lebih lambat di-query)"]]}],"so":[{"q":"Tambahkan constraint agar email pelanggan wajib mengandung tanda @.","h":"ALTER TABLE ... ADD CONSTRAINT ... CHECK (email LIKE ...).","a":"ALTER TABLE penjualan.pelanggan\n  ADD CONSTRAINT email_valid CHECK (email LIKE '%@%');","lang":"sql"}],"pts":["Uang pakai numeric, waktu pakai timestamptz.","Constraint menjaga data di level paling bawah.","CHECK, FOREIGN KEY, UNIQUE, EXCLUDE."],"q":[["Tipe yang tepat untuk harga Rp15.500,50?",["numeric(12,2)","real","text"],0,"Presisi desimal tepat."],["Apa yang terjadi jika menghapus produk yang masih punya pesanan dengan ON DELETE RESTRICT?",["Penghapusan ditolak","Pesanan ikut terhapus","produk_id menjadi NULL"],0,"RESTRICT mencegah data yatim."]],"deep":{"ist":[["numeric vs float","Uang wajib numeric (tepat); float/double punya galat pembulatan biner."],["timestamptz","Waktu dengan zona; disimpan dalam UTC dan ditampilkan sesuai TimeZone sesi. Pilihan default untuk kejadian nyata."],["CHECK constraint","Aturan bisnis di level database, misalnya total >= 0 atau status dalam daftar tertentu."],["Foreign key ON DELETE","Perilaku saat baris induk dihapus: RESTRICT, CASCADE, SET NULL."],["Exclusion constraint","Mencegah baris yang \"bertabrakan\", misalnya dua booking ruangan yang jamnya tumpang tindih."]],"cx":[{"t":"Kenapa uang memakai numeric, dan constraint menolak data salah","b":"Validasi di aplikasi bisa dilewati (skrip impor, query manual); constraint di database selalu berlaku.","code":"SELECT 0.1::float8 + 0.2::float8 = 0.3::float8 AS float_sama, 0.1::numeric + 0.2::numeric = 0.3 AS numeric_sama;\n\nCREATE TABLE transaksi (\n  id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,\n  nominal numeric(14,0) NOT NULL CHECK (nominal > 0),\n  status text NOT NULL CHECK (status IN ('pending', 'sukses', 'gagal')),\n  waktu timestamptz NOT NULL DEFAULT now()\n);\nINSERT INTO transaksi (nominal, status) VALUES (50000, 'sukses');\nINSERT INTO transaksi (nominal, status) VALUES (-1, 'sukses');\nINSERT INTO transaksi (nominal, status) VALUES (50000, 'SUKSES');","lang":"sql","out":" float_sama | numeric_sama\n------------+--------------\n f          | t\n(1 row)\n\nERROR:  new row for relation \"transaksi\" violates check constraint \"transaksi_nominal_check\"\nDETAIL:  Failing row contains (2, -1, sukses, 2026-11-19 15:13:42.518722+07).\nERROR:  new row for relation \"transaksi\" violates check constraint \"transaksi_status_check\"\nDETAIL:  Failing row contains (3, 50000, SUKSES, 2026-11-19 15:13:42.518913+07)."},{"t":"Exclusion constraint: booking ruang rapat tidak boleh bentrok","code":"CREATE EXTENSION IF NOT EXISTS btree_gist;\nCREATE TABLE booking (\n  ruang text NOT NULL,\n  waktu tstzrange NOT NULL,\n  EXCLUDE USING gist (ruang WITH =, waktu WITH &&)\n);\nINSERT INTO booking VALUES ('Rapat-1', '[2026-11-20 09:00+07, 2026-11-20 10:00+07)');\nINSERT INTO booking VALUES ('Rapat-1', '[2026-11-20 10:00+07, 2026-11-20 11:00+07)');   -- tepat bersambung: boleh\nINSERT INTO booking VALUES ('Rapat-1', '[2026-11-20 09:30+07, 2026-11-20 10:30+07)');   -- tumpang tindih: ditolak","lang":"sql","out":"ERROR:  conflicting key value violates exclusion constraint \"booking_ruang_waktu_excl\"\nDETAIL:  Key (ruang, waktu)=(Rapat-1, [\"2026-11-20 09:30:00+07\",\"2026-11-20 10:30:00+07\")) conflicts with existing key (ruang, waktu)=(Rapat-1, [\"2026-11-20 09:00:00+07\",\"2026-11-20 10:00:00+07\"))."}]}},{"b":["<b>JSONB</b> menyimpan JSON dalam bentuk biner yang bisa diindeks. Operator penting: <code>-&gt;</code> mengambil nilai sebagai JSON, <code>-&gt;&gt;</code> sebagai teks, <code>@&gt;</code> \"mengandung\", dan <code>?</code> \"punya kunci\". Indeks <b>GIN</b> membuat pencarian <code>@&gt;</code> cepat.","JSONB cocok untuk atribut yang bervariasi (spesifikasi produk elektronik berbeda dengan pakaian) atau payload dari API pihak ketiga. Jangan memasukkan semua ke JSONB: kolom yang sering difilter, di-JOIN, atau wajib ada sebaiknya kolom biasa dengan constraint.","Tipe lain yang berguna: <code>tstzrange</code> untuk rentang waktu, <code>inet</code> untuk alamat IP, dan <code>enum</code> untuk pilihan tetap."],"lang":"sql","code":"ALTER TABLE produk ADD COLUMN spek jsonb DEFAULT '{}';\n\nUPDATE produk SET spek = '{\"asal\": \"Aceh\", \"roast\": \"medium\", \"berat_g\": 250}'\nWHERE nama = 'Kopi Gayo';\n\nCREATE INDEX produk_spek_gin ON produk USING gin (spek);\n\nSELECT nama, spek->>'asal' AS asal, (spek->>'berat_g')::int AS gram\nFROM produk\nWHERE spek @> '{\"roast\": \"medium\"}';","out":"ALTER TABLE\nUPDATE 1\nCREATE INDEX\n   nama    | asal | gram\n-----------+------+------\n Kopi Gayo | Aceh |  250\n(1 row)","run":false,"so":[{"q":"Ambil nama produk yang spek-nya punya kunci <code>garansi</code>.","h":"Operator ? memeriksa keberadaan kunci.","a":"SELECT nama FROM produk WHERE spek ? 'garansi';","lang":"sql"}],"pts":["-&gt; JSON, -&gt;&gt; teks, @&gt; mengandung.","Indeks GIN untuk query JSONB.","Kolom penting tetap jadi kolom biasa."],"q":[["Operator yang mengembalikan nilai JSONB sebagai teks?",["->>","->","@>"],0,"Dua panah = teks."]],"deep":{"ist":[["JSONB","JSON biner yang bisa diindeks; cocok untuk atribut fleksibel, bukan pengganti seluruh skema relasional."],["Operator ->, ->>, @>","Ambil nilai JSON, ambil sebagai teks, dan \"berisi\" (containment) yang didukung indeks GIN."],["GIN index","Generalized Inverted Index untuk JSONB, array, dan full-text search."],["Array dan range","Tipe bawaan PostgreSQL: text[], int4range, tstzrange beserta operatornya."],["Generated column","Kolom yang nilainya dihitung otomatis dari kolom lain (GENERATED ALWAYS AS ... STORED)."]],"cx":[{"t":"Atribut produk fleksibel dengan JSONB dan indeks GIN","code":"CREATE TABLE produk (id serial PRIMARY KEY, nama text, atribut jsonb NOT NULL DEFAULT '{}');\nINSERT INTO produk (nama, atribut) VALUES\n ('Kopi Gayo 250g', '{\"jenis\": \"arabika\", \"roast\": \"medium\", \"asal\": \"Aceh\", \"halal\": true}'),\n ('Kopi Toraja 250g', '{\"jenis\": \"arabika\", \"roast\": \"dark\", \"asal\": \"Sulawesi Selatan\", \"halal\": true}'),\n ('Teh Melati', '{\"jenis\": \"teh\", \"kemasan\": \"celup\", \"isi\": 25}');\nCREATE INDEX produk_atribut_gin ON produk USING gin (atribut jsonb_path_ops);\n\nSELECT nama, atribut->>'asal' AS asal FROM produk WHERE atribut @> '{\"jenis\": \"arabika\"}';\nUPDATE produk SET atribut = atribut || '{\"stok_gudang\": 120}' WHERE nama LIKE 'Kopi Gayo%';\nSELECT nama, jsonb_pretty(atribut) FROM produk WHERE id = 1;","lang":"sql","out":"       nama       |       asal\n------------------+------------------\n Kopi Gayo 250g   | Aceh\n Kopi Toraja 250g | Sulawesi Selatan\n(2 rows)\n\n      nama      |      jsonb_pretty\n----------------+-------------------------\n Kopi Gayo 250g | {                      +\n                |     \"asal\": \"Aceh\",    +\n                |     \"halal\": true,     +\n                |     \"jenis\": \"arabika\",+\n                |     \"roast\": \"medium\", +\n                |     \"stok_gudang\": 120 +\n                | }\n(1 row)"}]}},{"b":["Di PostgreSQL, pengguna dan grup sama-sama <b>role</b>. Role dengan atribut <code>LOGIN</code> bisa masuk; role tanpa LOGIN dipakai sebagai grup. Hak diberikan dengan <code>GRANT</code> dan dicabut dengan <code>REVOKE</code>.","Terapkan <b>least privilege</b>: aplikasi web cukup SELECT, INSERT, UPDATE, DELETE di schema-nya, bukan superuser. Buat role grup (<code>baca_saja</code>, <code>aplikasi</code>), beri hak ke grup, lalu masukkan pengguna ke grup. Saat karyawan keluar, cukup cabut keanggotaannya.","<code>ALTER DEFAULT PRIVILEGES</code> memastikan tabel yang dibuat nanti otomatis mendapat hak yang sama; tanpa ini, tabel baru tidak bisa dibaca role baca_saja."],"lang":"sql","code":"CREATE ROLE baca_saja NOLOGIN;\nGRANT USAGE ON SCHEMA penjualan TO baca_saja;\nGRANT SELECT ON ALL TABLES IN SCHEMA penjualan TO baca_saja;\nALTER DEFAULT PRIVILEGES IN SCHEMA penjualan\n  GRANT SELECT ON TABLES TO baca_saja;\n\nCREATE ROLE dewi LOGIN PASSWORD 'ganti_segera' IN ROLE baca_saja;\n\nSET ROLE dewi;\nDELETE FROM penjualan.pelanggan WHERE id = 1;","out":"CREATE ROLE\nGRANT\nGRANT\nALTER DEFAULT PRIVILEGES\nCREATE ROLE\nSET\nERROR:  permission denied for table pelanggan","run":false,"so":[{"q":"Buat role grup <code>aplikasi</code> yang boleh SELECT, INSERT, UPDATE, DELETE di semua tabel schema penjualan, lalu buat user <code>webapp</code> sebagai anggotanya.","h":"GRANT USAGE pada schema, lalu GRANT hak DML, lalu CREATE ROLE ... IN ROLE.","a":"CREATE ROLE aplikasi NOLOGIN;\nGRANT USAGE ON SCHEMA penjualan TO aplikasi;\nGRANT SELECT, INSERT, UPDATE, DELETE ON ALL TABLES IN SCHEMA penjualan TO aplikasi;\nCREATE ROLE webapp LOGIN PASSWORD 'ganti_segera' IN ROLE aplikasi;","lang":"sql"}],"pts":["Pengguna dan grup sama-sama role.","Beri hak ke grup, masukkan pengguna ke grup.","ALTER DEFAULT PRIVILEGES untuk tabel yang dibuat nanti."],"q":[["Role yang tepat untuk aplikasi web produksi?",["Role khusus dengan hak DML di schema-nya","postgres (superuser)","Role dengan CREATEDB dan CREATEROLE"],0,"Hak minimum mengurangi dampak kebocoran."]],"deep":{"ist":[["Role","Identitas di PostgreSQL; bisa berupa pengguna (LOGIN) atau grup."],["Least privilege","Beri hak sekecil mungkin; aplikasi tidak memakai superuser atau pemilik tabel."],["Group role","Role tanpa LOGIN yang menampung hak; pengguna menjadi anggotanya (GRANT grup TO pengguna)."],["Default privileges","Hak otomatis untuk tabel yang dibuat di masa depan (ALTER DEFAULT PRIVILEGES)."],["Predefined roles","Role bawaan seperti pg_read_all_data, pg_monitor untuk tugas umum."]],"cx":[{"t":"Role baca/tulis untuk aplikasi dan role analis yang hanya bisa membaca","code":"CREATE TABLE pesanan (id int PRIMARY KEY, total numeric);\nINSERT INTO pesanan VALUES (1, 85000);\n\nCREATE ROLE app_baca NOLOGIN;\nCREATE ROLE app_tulis NOLOGIN IN ROLE app_baca;\nGRANT USAGE ON SCHEMA public TO app_baca;\nGRANT SELECT ON ALL TABLES IN SCHEMA public TO app_baca;\nGRANT INSERT, UPDATE ON ALL TABLES IN SCHEMA public TO app_tulis;\nALTER DEFAULT PRIVILEGES IN SCHEMA public GRANT SELECT ON TABLES TO app_baca;\nCREATE ROLE analis LOGIN IN ROLE app_baca;\n\nSET ROLE analis;\nSELECT * FROM pesanan;\nDELETE FROM pesanan;\nRESET ROLE;\n\nSELECT grantee, privilege_type FROM information_schema.role_table_grants\nWHERE table_name = 'pesanan' AND grantee LIKE 'app_%' ORDER BY 1, 2;","lang":"sql","setup":"SET client_min_messages = warning;\nDROP ROLE IF EXISTS app_baca, app_tulis, analis, kasir_medan, kasir_bdg, toko_app;\nRESET client_min_messages;","out":" id | total\n----+-------\n  1 | 85000\n(1 row)\n\nERROR:  permission denied for table pesanan\n  grantee  | privilege_type\n-----------+----------------\n app_baca  | SELECT\n app_tulis | INSERT\n app_tulis | UPDATE\n(3 rows)"}]}},{"b":["File <code>pg_hba.conf</code> mengatur <b>siapa boleh terhubung dari mana dan dengan metode apa</b>. Setiap baris berisi: tipe koneksi, database, user, alamat, dan metode. Baris dibaca dari atas; baris pertama yang cocok yang dipakai.","Metode yang disarankan: <code>scram-sha-256</code> untuk kata sandi (bukan <code>md5</code> lama, apalagi <code>trust</code>). Batasi alamat ke jaringan aplikasi saja, jangan <code>0.0.0.0/0</code>. Pakai <code>hostssl</code> agar koneksi wajib terenkripsi.","Setelah mengubah file, jalankan <code>SELECT pg_reload_conf();</code>. Periksa hasilnya di view <code>pg_hba_file_rules</code> untuk menemukan baris yang salah ketik."],"lang":"bash","code":"# TYPE   DATABASE  USER      ADDRESS          METHOD\nlocal    all       postgres                   peer\nhostssl  tokodb    webapp    10.0.1.0/24      scram-sha-256\nhostssl  tokodb    +baca_saja 10.0.2.0/24     scram-sha-256\nhost     all       all       0.0.0.0/0        reject\n\n# postgresql.conf\nssl = on\npassword_encryption = scram-sha-256","out":"SELECT pg_reload_conf();\n pg_reload_conf\n----------------\n t","run":false,"so":[{"q":"Tulis baris pg_hba.conf agar user <code>laporan</code> hanya bisa masuk ke database <code>tokodb</code> dari IP 192.168.10.20 dengan SSL dan scram-sha-256.","h":"Alamat satu host memakai /32.","a":"hostssl  tokodb  laporan  192.168.10.20/32  scram-sha-256","lang":"sql"}],"pts":["pg_hba.conf dibaca dari atas, baris pertama yang cocok menang.","Pakai scram-sha-256 dan hostssl.","Tutup dengan baris reject di akhir."],"q":[["Metode yang tidak boleh dipakai di produksi untuk koneksi jaringan?",["trust","scram-sha-256","cert"],0,"trust tidak meminta kata sandi."]],"deep":{"ist":[["pg_hba.conf","Aturan siapa boleh terhubung dari mana dan dengan metode apa; dibaca dari atas, aturan pertama yang cocok berlaku."],["scram-sha-256","Metode password modern; md5 dan trust (tanpa password) sebaiknya tidak dipakai di produksi."],["hostssl","Jenis koneksi yang hanya cocok jika memakai TLS; tolak koneksi tanpa enkripsi dari jaringan."],["Connection pooler","PgBouncer/pgcat: menampung ribuan koneksi aplikasi ke sedikit koneksi database."]],"cx":[{"t":"pg_hba.conf produksi yang ketat","code":"# TYPE    DATABASE  USER         ADDRESS          METHOD\nlocal     all       postgres                      peer                 # superuser hanya dari OS user postgres\nhostssl   toko      toko_app     10.10.1.0/24     scram-sha-256        # subnet server aplikasi\nhostssl   toko      +analis      10.20.0.0/16     scram-sha-256        # anggota grup analis dari VPN kantor\nhostssl   replication replikator 10.10.9.11/32    scram-sha-256        # standby\nhost      all       all          0.0.0.0/0        reject               # sisanya ditolak\n\n# postgresql.conf\nssl = on\nssl_min_protocol_version = 'TLSv1.3'\npassword_encryption = 'scram-sha-256'\n# muat ulang tanpa restart: SELECT pg_reload_conf();","lang":"conf"},{"t":"Memeriksa aturan yang sedang aktif dan metode password","b":"pg_hba_file_rules menampilkan isi pg_hba.conf beserta kesalahan sintaksnya sebelum di-reload. Cluster latihan ini memakai trust, yang tidak boleh dipakai di produksi.","code":"SELECT line_number, type, database, user_name, address, auth_method\nFROM pg_hba_file_rules ORDER BY line_number;\nSHOW password_encryption;","lang":"sql","out":" line_number | type  |   database    | user_name |  address  | auth_method\n-------------+-------+---------------+-----------+-----------+-------------\n         117 | local | {all}         | {all}     |           | trust\n         119 | host  | {all}         | {all}     | 127.0.0.1 | trust\n         121 | host  | {all}         | {all}     | ::1       | trust\n         124 | local | {replication} | {all}     |           | trust\n         125 | host  | {replication} | {all}     | 127.0.0.1 | trust\n         126 | host  | {replication} | {all}     | ::1       | trust\n(6 rows)\n\n password_encryption\n---------------------\n scram-sha-256\n(1 row)"}]}},{"b":["<b>Row-Level Security (RLS)</b> membatasi <b>baris</b> mana yang boleh dilihat atau diubah oleh setiap pengguna, langsung di database. Cocok untuk aplikasi multi-tenant: data toko A tidak boleh terlihat oleh toko B walaupun ada bug di query aplikasi.","Aktifkan dengan <code>ALTER TABLE ... ENABLE ROW LEVEL SECURITY</code>, lalu buat <code>POLICY</code> berisi kondisi <code>USING</code> (baris yang boleh dibaca) dan <code>WITH CHECK</code> (baris yang boleh ditulis). Supabase memakai RLS sebagai fondasi keamanannya.","Pemilik tabel dan superuser melewati RLS kecuali memakai <code>FORCE ROW LEVEL SECURITY</code>. Uji kebijakan dengan beberapa role sebelum rilis."],"lang":"sql","code":"CREATE TABLE pesanan_toko (\n  id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,\n  toko text NOT NULL,\n  total numeric(12,2)\n);\nINSERT INTO pesanan_toko (toko, total) VALUES\n  ('toko_a', 150000), ('toko_b', 90000), ('toko_a', 45000);\n\nALTER TABLE pesanan_toko ENABLE ROW LEVEL SECURITY;\nCREATE POLICY milik_sendiri ON pesanan_toko\n  USING (toko = current_setting('app.toko'));\n\nGRANT SELECT ON pesanan_toko TO baca_saja;\nSET ROLE dewi;\nSET app.toko = 'toko_a';\nSELECT * FROM pesanan_toko;","out":" id |  toko  |   total\n----+--------+-----------\n  1 | toko_a | 150000.00\n  3 | toko_a |  45000.00\n(2 rows)","run":false,"pts":["RLS = filter baris otomatis per pengguna.","USING untuk baca, WITH CHECK untuk tulis.","Pemilik tabel melewati RLS kecuali FORCE."],"q":[["Kapan RLS paling berguna?",["Aplikasi multi-tenant yang berbagi tabel","Tabel konfigurasi satu baris","Database yang hanya dipakai satu orang"],0,"Lapisan pengaman kedua di bawah aplikasi."]],"deep":{"ist":[["Row-Level Security (RLS)","Kebijakan per baris: pengguna hanya melihat atau mengubah baris yang diizinkan."],["Policy","Aturan USING (baris mana yang terlihat) dan WITH CHECK (baris mana yang boleh ditulis)."],["Multi-tenant","Satu database untuk banyak pelanggan/cabang; RLS memastikan data antar-tenant tidak bocor."],["BYPASSRLS / FORCE","Pemilik tabel dan superuser melewati RLS kecuali FORCE ROW LEVEL SECURITY."]],"cx":[{"t":"Kasir hanya melihat transaksi cabangnya sendiri","b":"Aplikasi mengatur app.cabang dari token login; walaupun query lupa menulis WHERE cabang, data cabang lain tidak bocor.","code":"CREATE TABLE transaksi (id int PRIMARY KEY, cabang text NOT NULL, total numeric NOT NULL);\nINSERT INTO transaksi VALUES (1, 'medan', 125000), (2, 'bandung', 98000), (3, 'medan', 47000);\nALTER TABLE transaksi ENABLE ROW LEVEL SECURITY;\nCREATE POLICY per_cabang ON transaksi\n  USING (cabang = current_setting('app.cabang'))\n  WITH CHECK (cabang = current_setting('app.cabang'));\n\nCREATE ROLE kasir_medan LOGIN;\nGRANT SELECT, INSERT ON transaksi TO kasir_medan;\n\nSET ROLE kasir_medan;\nSET app.cabang = 'medan';\nSELECT * FROM transaksi;\nINSERT INTO transaksi VALUES (4, 'bandung', 10000);\nRESET ROLE;","lang":"sql","setup":"SET client_min_messages = warning;\nDROP ROLE IF EXISTS app_baca, app_tulis, analis, kasir_medan, kasir_bdg, toko_app;\nRESET client_min_messages;","out":" id | cabang | total\n----+--------+--------\n  1 | medan  | 125000\n  3 | medan  |  47000\n(2 rows)\n\nERROR:  new row violates row-level security policy for table \"transaksi\""}]}},{"b":["<b>Transaksi</b> mengelompokkan beberapa perintah menjadi satu kesatuan: semua berhasil (<code>COMMIT</code>) atau semua dibatalkan (<code>ROLLBACK</code>). Contoh klasik: transfer saldo harus mengurangi rekening A <b>dan</b> menambah rekening B.","<b>ACID</b>: Atomicity (semua atau tidak sama sekali), Consistency (constraint tetap terpenuhi), Isolation (transaksi bersamaan tidak saling mengacaukan), Durability (yang sudah COMMIT tidak hilang walau server mati).","Tingkat isolasi PostgreSQL: <b>Read Committed</b> (bawaan, setiap perintah melihat data yang sudah di-commit saat itu), <b>Repeatable Read</b> (melihat snapshot yang sama sepanjang transaksi), dan <b>Serializable</b> (seolah transaksi berjalan bergantian; aplikasi harus siap mengulang jika muncul error serialisasi)."],"lang":"sql","code":"CREATE TABLE rekening (no text PRIMARY KEY, saldo numeric(14,2) CHECK (saldo >= 0));\nINSERT INTO rekening VALUES ('A', 500000), ('B', 100000);\n\nBEGIN;\nUPDATE rekening SET saldo = saldo - 700000 WHERE no = 'A';\n-- gagal: saldo menjadi negatif\nROLLBACK;\n\nBEGIN;\nUPDATE rekening SET saldo = saldo - 200000 WHERE no = 'A';\nUPDATE rekening SET saldo = saldo + 200000 WHERE no = 'B';\nCOMMIT;\nSELECT * FROM rekening;","out":"ERROR:  new row for relation \"rekening\" violates check constraint \"rekening_saldo_check\"\nROLLBACK\nBEGIN\nUPDATE 1\nUPDATE 1\nCOMMIT\n no |   saldo\n----+-----------\n A  | 300000.00\n B  | 300000.00","run":false,"tb":[{"c":"Fenomena per tingkat isolasi di PostgreSQL","h":["Tingkat","Dirty read","Non-repeatable read","Phantom","Anomali serialisasi"],"r":[["Read Committed","Tidak","Mungkin","Mungkin","Mungkin"],["Repeatable Read","Tidak","Tidak","Tidak","Mungkin"],["Serializable","Tidak","Tidak","Tidak","Tidak"]]}],"so":[{"q":"Tulis transaksi yang memindahkan stok 5 unit dari gudang Medan ke gudang Binjai di tabel <code>stok(gudang, jumlah)</code>.","h":"Dua UPDATE di dalam BEGIN ... COMMIT.","a":"BEGIN;\nUPDATE stok SET jumlah = jumlah - 5 WHERE gudang = 'Medan';\nUPDATE stok SET jumlah = jumlah + 5 WHERE gudang = 'Binjai';\nCOMMIT;","lang":"sql"}],"pts":["BEGIN, COMMIT, ROLLBACK.","ACID menjamin data tetap benar.","Read Committed bawaan; Serializable paling ketat."],"q":[["Huruf D pada ACID menjamin apa?",["Data yang sudah COMMIT tidak hilang","Data tidak duplikat","Query cepat"],0,"Durability, berkat WAL."]],"deep":{"ist":[["ACID","Atomicity, Consistency, Isolation, Durability: jaminan transaksi database."],["Read Committed","Default PostgreSQL: setiap statement melihat data yang sudah di-commit saat statement dimulai."],["Repeatable Read / Serializable","Snapshot tetap sepanjang transaksi; Serializable juga mencegah anomali seperti write skew."],["Savepoint","Titik simpan di dalam transaksi untuk membatalkan sebagian tanpa membatalkan semuanya."],["SELECT ... FOR UPDATE","Mengunci baris yang dibaca agar tidak diubah transaksi lain sampai commit (cegah lost update)."]],"cx":[{"t":"Transfer saldo yang atomik dan savepoint","b":"Setelah satu statement gagal, PostgreSQL menolak statement berikutnya dalam transaksi itu sampai ROLLBACK. Tidak ada transfer setengah jadi.","code":"CREATE TABLE rekening (id text PRIMARY KEY, saldo numeric NOT NULL CHECK (saldo >= 0));\nINSERT INTO rekening VALUES ('A', 100000), ('B', 50000);\n\nBEGIN;\nUPDATE rekening SET saldo = saldo - 150000 WHERE id = 'A';     -- melanggar CHECK\nUPDATE rekening SET saldo = saldo + 150000 WHERE id = 'B';\nCOMMIT;                                                        -- transaksi gagal -> ROLLBACK\nSELECT * FROM rekening ORDER BY id;\n\nBEGIN;\nUPDATE rekening SET saldo = saldo - 30000 WHERE id = 'A';\nSAVEPOINT sebelum_bonus;\nUPDATE rekening SET saldo = saldo + 999999 WHERE id = 'B';     -- salah input\nROLLBACK TO SAVEPOINT sebelum_bonus;\nUPDATE rekening SET saldo = saldo + 30000 WHERE id = 'B';\nCOMMIT;\nSELECT * FROM rekening ORDER BY id;","lang":"sql","out":"ERROR:  new row for relation \"rekening\" violates check constraint \"rekening_saldo_check\"\nDETAIL:  Failing row contains (A, -50000).\nERROR:  current transaction is aborted, commands ignored until end of transaction block\n id | saldo\n----+--------\n A  | 100000\n B  |  50000\n(2 rows)\n\n id | saldo\n----+-------\n A  | 70000\n B  | 80000\n(2 rows)"}]}},{"b":["PostgreSQL memakai <b>MVCC</b> (Multi-Version Concurrency Control): UPDATE tidak menimpa baris, melainkan membuat <b>versi baru</b> dan menandai versi lama sebagai mati. Setiap baris punya kolom tersembunyi <code>xmin</code> (transaksi pembuat) dan <code>xmax</code> (transaksi penghapus). Hasilnya: <b>pembaca tidak menghalangi penulis dan sebaliknya</b>.","Penulis yang mengubah baris yang sama tetap harus antre lewat <b>row lock</b>. Perintah seperti <code>ALTER TABLE</code> butuh lock tabel yang berat. Lihat siapa menunggu siapa dengan <code>pg_locks</code> dan <code>pg_blocking_pids()</code>.","<b>Deadlock</b> terjadi jika transaksi 1 menunggu baris yang dikunci transaksi 2, sementara transaksi 2 menunggu baris milik transaksi 1. PostgreSQL mendeteksinya setelah <code>deadlock_timeout</code> (1 detik) dan membatalkan salah satunya. Pencegahan: selalu kunci baris dalam urutan yang sama."],"lang":"sql","code":"-- siapa yang sedang memblokir siapa\nSELECT pid,\n       pg_blocking_pids(pid) AS diblokir_oleh,\n       now() - query_start AS lama,\n       left(query, 40) AS query\nFROM pg_stat_activity\nWHERE cardinality(pg_blocking_pids(pid)) > 0;","out":" pid  | diblokir_oleh |      lama       |                  query\n------+---------------+-----------------+------------------------------------------\n 4127 | {4093}        | 00:00:12.48     | UPDATE rekening SET saldo = saldo + 1000\n(1 row)","run":false,"so":[{"q":"Tulis perintah untuk menghentikan backend dengan pid 4093 yang memblokir.","h":"pg_cancel_backend membatalkan query, pg_terminate_backend memutus koneksi.","a":"SELECT pg_terminate_backend(4093);","lang":"sql"}],"pts":["MVCC: UPDATE membuat versi baru, pembaca tidak terblokir.","pg_blocking_pids() menunjukkan rantai blokir.","Cegah deadlock dengan urutan penguncian yang sama."],"q":[["Dengan MVCC, apakah SELECT panjang memblokir UPDATE?",["Tidak","Ya, selalu","Hanya di Serializable"],0,"Pembaca melihat snapshot lama."]],"deep":{"ist":[["MVCC","Multi-Version Concurrency Control: UPDATE membuat versi baris baru sehingga pembaca tidak menunggu penulis."],["xmin / xmax","ID transaksi yang membuat dan menghapus sebuah versi baris (kolom sistem tersembunyi)."],["Row lock vs table lock","Kunci per baris (FOR UPDATE) vs kunci tabel (ALTER TABLE, LOCK TABLE) yang memblokir lebih luas."],["Deadlock","Dua transaksi saling menunggu kunci; PostgreSQL mendeteksinya setelah deadlock_timeout dan membatalkan salah satu."],["lock_timeout","Batas waktu menunggu kunci; wajib saat migrasi agar ALTER TABLE tidak menahan antrean query."]],"cx":[{"t":"Melihat MVCC: UPDATE membuat versi baris baru","b":"ctid (posisi fisik) berubah dari (0,1) ke (0,2): versi lama masih ada di halaman sampai dibersihkan VACUUM.","code":"CREATE TABLE produk (id int PRIMARY KEY, harga int);\nINSERT INTO produk VALUES (1, 85000);\nSELECT ctid, xmin, xmax, * FROM produk;\nUPDATE produk SET harga = 90000 WHERE id = 1;\nSELECT ctid, xmin, xmax, * FROM produk;","lang":"sql","out":" ctid  | xmin | xmax | id | harga\n-------+------+------+----+-------\n (0,1) | 1735 |    0 |  1 | 85000\n(1 row)\n\n ctid  | xmin | xmax | id | harga\n-------+------+------+----+-------\n (0,2) | 1736 |    0 |  1 | 90000\n(1 row)"},{"t":"Deadlock sungguhan dengan dua sesi (sesi kedua lewat dblink)","b":"Pencegahannya: kunci baris selalu dalam urutan yang sama (misalnya urut SKU), transaksi pendek, dan retry otomatis untuk error 40P01.","code":"CREATE EXTENSION IF NOT EXISTS dblink;\nCREATE TABLE stok (sku text PRIMARY KEY, qty int);\nINSERT INTO stok VALUES ('KOPI', 10), ('GULA', 10);\nSET deadlock_timeout = '200ms';\nSELECT dblink_connect('sesi_b', format('dbname=%s host=/tmp port=%s user=postgres', current_database(), current_setting('port')));\n\nBEGIN;\nUPDATE stok SET qty = qty - 1 WHERE sku = 'KOPI';                                    -- sesi A kunci KOPI\nSELECT dblink_exec('sesi_b', 'BEGIN; UPDATE stok SET qty = qty - 1 WHERE sku = ''GULA''');   -- sesi B kunci GULA\nSELECT dblink_send_query('sesi_b', 'UPDATE stok SET qty = qty - 1 WHERE sku = ''KOPI''');    -- B menunggu A\nSELECT pg_sleep(0.3);\nUPDATE stok SET qty = qty - 1 WHERE sku = 'GULA';                                    -- A menunggu B -> deadlock\nROLLBACK;\nSELECT dblink_disconnect('sesi_b');","lang":"sql","out":" dblink_connect\n----------------\n OK\n(1 row)\n\n dblink_exec\n-------------\n UPDATE 1\n(1 row)\n\n dblink_send_query\n-------------------\n                 1\n(1 row)\n\n pg_sleep\n----------\n\n(1 row)\n\nERROR:  deadlock detected\nDETAIL:  Process 21799 waits for ShareLock on transaction 1743; blocked by process 21800.\nProcess 21800 waits for ShareLock on transaction 1742; blocked by process 21799.\nHINT:  See server log for query details.\nCONTEXT:  while updating tuple (0,2) in relation \"stok\"\n dblink_disconnect\n-------------------\n OK\n(1 row)"}]}},{"b":["Versi baris yang sudah mati (<b>dead tuple</b>) akibat MVCC tetap menempati ruang. <b>VACUUM</b> menandai ruang itu agar bisa dipakai ulang dan memperbarui <b>visibility map</b>. Jika tidak di-vacuum, tabel dan indeks membengkak (<b>bloat</b>) dan query melambat.","<b>Autovacuum</b> berjalan otomatis berdasarkan jumlah baris mati. Untuk tabel besar yang sering di-update, turunkan <code>autovacuum_vacuum_scale_factor</code> per tabel. <code>VACUUM FULL</code> mengembalikan ruang ke sistem operasi tetapi mengunci tabel sepenuhnya; di produksi pakai extension <b>pg_repack</b>.","VACUUM juga mencegah <b>transaction ID wraparound</b>: ID transaksi 32-bit akan berputar setelah sekitar 2 miliar transaksi. Pantau umur <code>datfrozenxid</code>; jika terlalu tua, PostgreSQL akan berhenti menerima tulisan demi keamanan data."],"lang":"sql","code":"SELECT relname, n_live_tup, n_dead_tup,\n       round(100.0 * n_dead_tup / nullif(n_live_tup + n_dead_tup, 0), 1) AS persen_mati,\n       last_autovacuum\nFROM pg_stat_user_tables\nORDER BY n_dead_tup DESC\nLIMIT 3;\n\nALTER TABLE pesanan SET (autovacuum_vacuum_scale_factor = 0.02);\nVACUUM (VERBOSE, ANALYZE) pesanan;","out":"  relname   | n_live_tup | n_dead_tup | persen_mati |        last_autovacuum\n------------+------------+------------+-------------+-------------------------------\n pesanan    |    1203344 |     318002 |        20.9 | 2026-11-04 23:10:41.52+07\n rekening   |      50210 |       1840 |         3.5 | 2026-11-05 08:02:13.11+07\n produk     |       8420 |         12 |         0.1 |\n\nALTER TABLE\nINFO:  vacuuming \"tokodb.public.pesanan\"\nINFO:  finished vacuuming \"tokodb.public.pesanan\": index scans: 1\npages: 0 removed, 15872 remain, 15872 scanned (100.00% of total)\ntuples: 318002 removed, 1203344 remain, 0 are dead but not yet removable","run":false,"so":[{"q":"Tampilkan 5 tabel dengan dead tuple terbanyak beserta waktu autovacuum terakhir.","h":"View pg_stat_user_tables, urutkan n_dead_tup menurun.","a":"SELECT relname, n_dead_tup, last_autovacuum\nFROM pg_stat_user_tables\nORDER BY n_dead_tup DESC\nLIMIT 5;","lang":"sql"}],"pts":["Dead tuple dibersihkan oleh VACUUM.","Setel autovacuum per tabel untuk tabel besar.","Pantau wraparound lewat umur datfrozenxid."],"q":[["Risiko VACUUM FULL di jam sibuk?",["Tabel terkunci penuh selama proses","Data terhapus","Indeks hilang"],0,"Gunakan pg_repack sebagai gantinya."]],"deep":{"ist":[["Dead tuple","Versi baris lama hasil UPDATE/DELETE yang tidak lagi terlihat oleh transaksi mana pun."],["VACUUM","Menandai ruang dead tuple agar bisa dipakai ulang dan memperbarui visibility map; tidak mengunci baca/tulis."],["Bloat","Tabel/indeks membengkak karena ruang mati; memperlambat scan dan memboroskan cache."],["Transaction ID wraparound","Batas 2 miliar ID transaksi; VACUUM (freeze) wajib berjalan agar database tidak berhenti menerima tulisan."],["pg_repack","Ekstensi untuk membangun ulang tabel yang bloat tanpa kunci lama seperti VACUUM FULL."]],"cx":[{"t":"Mengukur dead tuple dan efek VACUUM","b":"VACUUM biasa mengosongkan ruang untuk dipakai ulang tetapi ukuran berkas tidak mengecil; VACUUM FULL atau pg_repack yang mengembalikan ruang ke OS.","code":"CREATE EXTENSION IF NOT EXISTS pgstattuple;\nCREATE TABLE sesi (id int PRIMARY KEY, data text) WITH (autovacuum_enabled = off);\nINSERT INTO sesi SELECT g, repeat('x', 200) FROM generate_series(1, 20000) g;\nUPDATE sesi SET data = repeat('y', 200);                -- setiap baris punya 1 versi mati\nDELETE FROM sesi WHERE id % 2 = 0;\n\nSELECT pg_size_pretty(table_len) AS ukuran, tuple_count AS hidup, dead_tuple_count AS mati,\n       round(dead_tuple_percent) AS persen_mati, round(free_percent) AS persen_kosong\nFROM pgstattuple('sesi');\n\nVACUUM sesi;\nSELECT pg_size_pretty(table_len) AS ukuran, tuple_count AS hidup, dead_tuple_count AS mati,\n       round(dead_tuple_percent) AS persen_mati, round(free_percent) AS persen_kosong\nFROM pgstattuple('sesi');","lang":"sql","out":" ukuran  | hidup | mati  | persen_mati | persen_kosong\n---------+-------+-------+-------------+---------------\n 9416 kB | 10000 | 10000 |          24 |            50\n(1 row)\n\n ukuran  | hidup | mati | persen_mati | persen_kosong\n---------+-------+------+-------------+---------------\n 9416 kB | 10000 |    0 |           0 |            75\n(1 row)"},{"t":"Menyetel autovacuum untuk tabel yang sering di-update","code":"-- Default: vacuum saat dead tuple > 50 + 20% baris. Untuk tabel 100 juta baris itu 20 juta baris mati!\nALTER TABLE pesanan SET (autovacuum_vacuum_scale_factor = 0.02, autovacuum_vacuum_threshold = 5000,\n                         autovacuum_analyze_scale_factor = 0.01);\n\n-- Pantau usia transaksi tertua (wraparound): waspada jika mendekati 1,5 miliar\nSELECT datname, age(datfrozenxid) FROM pg_database ORDER BY 2 DESC;","lang":"sql"}]}},{"b":["<b>Query planner</b> memilih cara tercepat menjalankan query berdasarkan <b>statistik</b> tabel (diperbarui oleh ANALYZE). <code>EXPLAIN</code> menampilkan rencana perkiraan; <code>EXPLAIN (ANALYZE, BUFFERS)</code> benar-benar menjalankan query dan menampilkan waktu nyata serta jumlah halaman yang dibaca.","Baca dari bagian paling dalam (paling menjorok) ke atas. Perhatikan: <b>Seq Scan</b> pada tabel besar dengan filter yang selektif (tanda butuh indeks), selisih besar antara <code>rows</code> perkiraan dan <code>actual rows</code> (statistik usang), serta <code>Sort Method: external merge Disk</code> (work_mem kurang).","Jenis join: <b>Nested Loop</b> (bagus untuk sedikit baris), <b>Hash Join</b> (tabel sedang sampai besar, butuh memori), dan <b>Merge Join</b> (kedua sisi sudah terurut). Situs explain.dalibo.com membantu memvisualkan rencana yang panjang."],"lang":"sql","code":"EXPLAIN (ANALYZE, BUFFERS)\nSELECT * FROM pesanan WHERE pelanggan_id = 4821;","out":" Seq Scan on pesanan  (cost=0.00..31872.80 rows=12 width=48) (actual time=0.042..187.531 rows=9 loops=1)\n   Filter: (pelanggan_id = 4821)\n   Rows Removed by Filter: 1203335\n   Buffers: shared hit=1920 read=13952\n Planning Time: 0.118 ms\n Execution Time: 187.566 ms","run":false,"pts":["Baca rencana dari dalam ke luar.","Seq Scan + banyak \"Rows Removed by Filter\" = kandidat indeks.","Perkiraan vs aktual jauh berbeda = jalankan ANALYZE."],"q":[["Rencana di atas membuang 1,2 juta baris untuk mendapat 9. Solusinya?",["Indeks pada pelanggan_id","Menambah RAM","VACUUM FULL"],0,"Filter sangat selektif."]],"deep":{"ist":[["Query plan","Rencana eksekusi yang dipilih planner berdasarkan statistik tabel."],["Seq Scan / Index Scan / Bitmap Heap Scan","Membaca seluruh tabel / mengikuti indeks per baris / mengumpulkan halaman dari indeks lalu membaca tabel."],["Estimated vs actual rows","Selisih besar antara perkiraan dan kenyataan menandakan statistik usang; jalankan ANALYZE."],["Buffers shared hit/read","Halaman yang ditemukan di cache vs dibaca dari disk (EXPLAIN (ANALYZE, BUFFERS))."],["Sargable","Kondisi yang bisa memakai indeks; fungsi pada kolom (date(dibuat) = ...) membuatnya tidak sargable."]],"cx":[{"t":"Dari Seq Scan ke pemindaian indeks pada 300 ribu pesanan","b":"Perhatikan \"Rows Removed by Filter\": tanpa indeks, dua proses paralel membuang hampir 300 ribu baris untuk menemukan 15. Dengan indeks, hanya 15 blok yang dibaca.","code":"CREATE TABLE pelanggan (id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY, nama text NOT NULL, kota text NOT NULL);\nCREATE TABLE pesanan (id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY, pelanggan_id bigint NOT NULL REFERENCES pelanggan,\n                      dibuat timestamptz NOT NULL, status text NOT NULL, total numeric(14,0) NOT NULL);\nINSERT INTO pelanggan (nama, kota)\nSELECT 'Pelanggan ' || g, (ARRAY['Medan','Bandung','Surabaya','Makassar','Denpasar'])[1 + g % 5] FROM generate_series(1, 20000) g;\nINSERT INTO pesanan (pelanggan_id, dibuat, status, total)\nSELECT 1 + (g::bigint * 7919) % 20000, timestamptz '2026-01-01 00:00+07' + (g % 320) * interval '1 day' + (g % 86400) * interval '1 second',\n       (ARRAY['baru','dibayar','dikirim','selesai','batal'])[1 + g % 5], 10000 + (g::bigint * 37) % 2000000\nFROM generate_series(1, 300000) g;\nANALYZE;\n\nEXPLAIN (ANALYZE, COSTS OFF, TIMING OFF, SUMMARY OFF)\nSELECT * FROM pesanan WHERE pelanggan_id = 4242;\n\nCREATE INDEX pesanan_pelanggan_idx ON pesanan (pelanggan_id);\n\nEXPLAIN (ANALYZE, COSTS OFF, TIMING OFF, SUMMARY OFF)\nSELECT * FROM pesanan WHERE pelanggan_id = 4242;","lang":"sql","out":"                         QUERY PLAN\n------------------------------------------------------------\n Gather (actual rows=15 loops=1)\n   Workers Planned: 1\n   Workers Launched: 1\n   ->  Parallel Seq Scan on pesanan (actual rows=8 loops=2)\n         Filter: (pelanggan_id = 4242)\n         Rows Removed by Filter: 149992\n(6 rows)\n\n                                QUERY PLAN\n---------------------------------------------------------------------------\n Bitmap Heap Scan on pesanan (actual rows=15 loops=1)\n   Recheck Cond: (pelanggan_id = 4242)\n   Heap Blocks: exact=15\n   ->  Bitmap Index Scan on pesanan_pelanggan_idx (actual rows=15 loops=1)\n         Index Cond: (pelanggan_id = 4242)\n(5 rows)"},{"t":"Fungsi pada kolom mematikan indeks (query tidak sargable)","code":"CREATE TABLE pelanggan (id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY, nama text NOT NULL, kota text NOT NULL);\nCREATE TABLE pesanan (id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY, pelanggan_id bigint NOT NULL REFERENCES pelanggan,\n                      dibuat timestamptz NOT NULL, status text NOT NULL, total numeric(14,0) NOT NULL);\nINSERT INTO pelanggan (nama, kota)\nSELECT 'Pelanggan ' || g, (ARRAY['Medan','Bandung','Surabaya','Makassar','Denpasar'])[1 + g % 5] FROM generate_series(1, 20000) g;\nINSERT INTO pesanan (pelanggan_id, dibuat, status, total)\nSELECT 1 + (g::bigint * 7919) % 20000, timestamptz '2026-01-01 00:00+07' + (g % 320) * interval '1 day' + (g % 86400) * interval '1 second',\n       (ARRAY['baru','dibayar','dikirim','selesai','batal'])[1 + g % 5], 10000 + (g::bigint * 37) % 2000000\nFROM generate_series(1, 300000) g;\nANALYZE;\nCREATE INDEX pesanan_dibuat_idx ON pesanan (dibuat);\n\nEXPLAIN (COSTS OFF)\nSELECT count(*) FROM pesanan WHERE date(dibuat AT TIME ZONE 'Asia/Jakarta') = '2026-06-01';\n\nEXPLAIN (COSTS OFF)\nSELECT count(*) FROM pesanan WHERE dibuat >= '2026-06-01 00:00+07' AND dibuat < '2026-06-02 00:00+07';","lang":"sql","out":"                                             QUERY PLAN\n-----------------------------------------------------------------------------------------------------\n Finalize Aggregate\n   ->  Gather\n         Workers Planned: 1\n         ->  Partial Aggregate\n               ->  Parallel Seq Scan on pesanan\n                     Filter: (date((dibuat AT TIME ZONE 'Asia/Jakarta'::text)) = '2026-06-01'::date)\n(6 rows)\n\n                                                                          QUERY PLAN\n--------------------------------------------------------------------------------------------------------------------------------------------------------------\n Aggregate\n   ->  Bitmap Heap Scan on pesanan\n         Recheck Cond: ((dibuat >= '2026-06-01 00:00:00+07'::timestamp with time zone) AND (dibuat < '2026-06-02 00:00:00+07'::timestamp with time zone))\n         ->  Bitmap Index Scan on pesanan_dibuat_idx\n               Index Cond: ((dibuat >= '2026-06-01 00:00:00+07'::timestamp with time zone) AND (dibuat < '2026-06-02 00:00:00+07'::timestamp with time zone))\n(5 rows)"}]}},{"b":["<b>B-tree</b> (bawaan) untuk <code>=</code>, <code>&lt;</code>, <code>&gt;</code>, BETWEEN, ORDER BY, dan LIKE dengan awalan tetap. <b>GIN</b> untuk JSONB, array, dan pencarian teks penuh. <b>GiST</b> untuk data geometri dan rentang. <b>BRIN</b> sangat kecil, untuk tabel raksasa yang datanya berurutan secara alami (log berdasarkan waktu). <b>Hash</b> hanya untuk <code>=</code>.","Indeks khusus: <b>komposit</b> (urutan kolom penting: kolom kesetaraan di depan), <b>partial</b> (<code>WHERE status = 'aktif'</code>), <b>expression</b> (<code>lower(email)</code>), dan <b>covering</b> (<code>INCLUDE</code>) agar terjadi Index Only Scan.","Indeks tidak gratis: memperlambat INSERT dan UPDATE serta memakan disk. Di produksi, buat dengan <code>CREATE INDEX CONCURRENTLY</code> agar tabel tidak terkunci, dan hapus indeks yang tidak pernah dipakai (lihat <code>pg_stat_user_indexes.idx_scan = 0</code>)."],"lang":"sql","code":"CREATE INDEX CONCURRENTLY pesanan_pelanggan_idx\n  ON pesanan (pelanggan_id, dibuat DESC);\n\nEXPLAIN (ANALYZE)\nSELECT * FROM pesanan WHERE pelanggan_id = 4821\nORDER BY dibuat DESC LIMIT 5;","out":"CREATE INDEX\n Limit  (cost=0.43..20.52 rows=5 width=48) (actual time=0.031..0.038 rows=5 loops=1)\n   ->  Index Scan using pesanan_pelanggan_idx on pesanan  (cost=0.43..48.65 rows=12 width=48) (actual time=0.030..0.036 rows=5 loops=1)\n         Index Cond: (pelanggan_id = 4821)\n Planning Time: 0.201 ms\n Execution Time: 0.059 ms","run":false,"tb":[{"c":"Memilih jenis indeks","h":["Jenis","Cocok untuk","Contoh"],"r":[["B-tree","Kesetaraan, rentang, urutan","WHERE harga BETWEEN 10000 AND 50000"],["GIN","JSONB, array, teks penuh","WHERE spek @> '{\"roast\":\"medium\"}'"],["GiST","Geometri, rentang, kedekatan","Lokasi terdekat (PostGIS)"],["BRIN","Tabel sangat besar berurutan","Log sensor per waktu"],["Partial","Sebagian baris","WHERE status = 'aktif'"],["Expression","Hasil fungsi","lower(email)"]]}],"so":[{"q":"Buat partial index untuk pesanan berstatus <code>menunggu</code> berdasarkan kolom dibuat.","h":"CREATE INDEX ... WHERE status = ...","a":"CREATE INDEX CONCURRENTLY pesanan_menunggu_idx\n  ON pesanan (dibuat)\n  WHERE status = 'menunggu';","lang":"sql"}],"pts":["B-tree untuk sebagian besar kasus.","Urutan kolom indeks komposit penting.","CREATE INDEX CONCURRENTLY di produksi."],"q":[["Indeks yang tepat untuk mempercepat <code>WHERE lower(email) = 'rina@contoh.id'</code>?",["Expression index pada lower(email)","B-tree biasa pada email","BRIN pada email"],0,"Indeks harus cocok dengan ekspresi di WHERE."],["Kenapa memakai CONCURRENTLY?",["Tabel tetap bisa ditulis selama indeks dibuat","Indeks jadi lebih kecil","Wajib untuk GIN"],0,"Tanpa lock tulis yang lama."]],"deep":{"ist":[["B-tree","Indeks default untuk =, <, >, BETWEEN, ORDER BY; urutan kolom pada indeks komposit penting."],["Partial index","Indeks untuk sebagian baris (WHERE status = 'baru'); kecil dan cepat."],["Covering index (INCLUDE)","Menyertakan kolom tambahan sehingga query cukup membaca indeks (Index Only Scan)."],["GIN / GiST / BRIN","GIN untuk JSONB/array/full-text, GiST untuk range dan geometri, BRIN untuk tabel log besar yang berurutan waktu."],["CREATE INDEX CONCURRENTLY","Membuat indeks di produksi tanpa memblokir INSERT/UPDATE."]],"cx":[{"t":"Membandingkan ukuran indeks penuh, partial, dan BRIN","b":"BRIN hanya puluhan KB untuk 300 ribu baris karena menyimpan ringkasan per blok, bukan per baris. Cocok untuk tabel log yang terus bertambah.","code":"CREATE TABLE pelanggan (id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY, nama text NOT NULL, kota text NOT NULL);\nCREATE TABLE pesanan (id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY, pelanggan_id bigint NOT NULL REFERENCES pelanggan,\n                      dibuat timestamptz NOT NULL, status text NOT NULL, total numeric(14,0) NOT NULL);\nINSERT INTO pelanggan (nama, kota)\nSELECT 'Pelanggan ' || g, (ARRAY['Medan','Bandung','Surabaya','Makassar','Denpasar'])[1 + g % 5] FROM generate_series(1, 20000) g;\nINSERT INTO pesanan (pelanggan_id, dibuat, status, total)\nSELECT 1 + (g::bigint * 7919) % 20000, timestamptz '2026-01-01 00:00+07' + (g % 320) * interval '1 day' + (g % 86400) * interval '1 second',\n       (ARRAY['baru','dibayar','dikirim','selesai','batal'])[1 + g % 5], 10000 + (g::bigint * 37) % 2000000\nFROM generate_series(1, 300000) g;\nANALYZE;\nCREATE INDEX idx_status_penuh ON pesanan (status, dibuat);\nCREATE INDEX idx_status_baru ON pesanan (dibuat) WHERE status = 'baru';\nCREATE INDEX idx_dibuat_brin ON pesanan USING brin (dibuat);\nCREATE INDEX idx_cover ON pesanan (pelanggan_id) INCLUDE (total);\nVACUUM ANALYZE pesanan;                      -- visibility map terisi -> Index Only Scan bisa dipakai\n\nSELECT indexrelname AS indeks, pg_size_pretty(pg_relation_size(indexrelid)) AS ukuran\nFROM pg_stat_user_indexes WHERE relname = 'pesanan' ORDER BY pg_relation_size(indexrelid) DESC;\n\nEXPLAIN (COSTS OFF) SELECT dibuat FROM pesanan WHERE status = 'baru' AND dibuat > '2026-11-01';\nEXPLAIN (COSTS OFF) SELECT sum(total) FROM pesanan WHERE pelanggan_id = 77;","lang":"sql","out":"      indeks      | ukuran\n------------------+---------\n idx_cover        | 9264 kB\n pesanan_pkey     | 6600 kB\n idx_status_penuh | 4952 kB\n idx_status_baru  | 848 kB\n idx_dibuat_brin  | 24 kB\n(5 rows)\n\n                                 QUERY PLAN\n-----------------------------------------------------------------------------\n Index Only Scan using idx_status_baru on pesanan\n   Index Cond: (dibuat > '2026-11-01 00:00:00+07'::timestamp with time zone)\n(2 rows)\n\n                    QUERY PLAN\n--------------------------------------------------\n Aggregate\n   ->  Index Only Scan using idx_cover on pesanan\n         Index Cond: (pelanggan_id = 77)\n(3 rows)"},{"t":"Pencarian teks \"mengandung\" dengan pg_trgm","b":"Indeks B-tree biasa tidak bisa dipakai untuk LIKE '%kata%'; trigram GIN bisa.","code":"CREATE EXTENSION IF NOT EXISTS pg_trgm;\nCREATE TABLE produk (id serial PRIMARY KEY, nama text);\nINSERT INTO produk (nama) SELECT 'Produk ' || md5(g::text) FROM generate_series(1, 50000) g;\nINSERT INTO produk (nama) VALUES ('Kopi Arabika Gayo 250g'), ('Kopi Robusta Lampung 1kg');\nCREATE INDEX produk_nama_trgm ON produk USING gin (nama gin_trgm_ops);\nANALYZE produk;\nEXPLAIN (COSTS OFF) SELECT nama FROM produk WHERE nama ILIKE '%arabika%';\nSELECT nama FROM produk WHERE nama ILIKE '%arabika%';","lang":"sql","out":"                    QUERY PLAN\n--------------------------------------------------\n Bitmap Heap Scan on produk\n   Recheck Cond: (nama ~~* '%arabika%'::text)\n   ->  Bitmap Index Scan on produk_nama_trgm\n         Index Cond: (nama ~~* '%arabika%'::text)\n(4 rows)\n\n          nama\n------------------------\n Kopi Arabika Gayo 250g\n(1 row)"}]}},{"b":["Extension <b>pg_stat_statements</b> mencatat statistik setiap bentuk query: berapa kali dipanggil, total waktu, rata-rata, dan baris. Ini titik awal tuning: perbaiki query dengan <b>total waktu</b> terbesar dulu, bukan yang paling lambat sekali jalan.","Parameter memori utama: <code>shared_buffers</code> sekitar 25% RAM; <code>effective_cache_size</code> sekitar 50 sampai 75% RAM (perkiraan cache OS untuk planner); <code>work_mem</code> per operasi sort atau hash (hati-hati, dikalikan jumlah koneksi dan operasi); <code>maintenance_work_mem</code> untuk VACUUM dan CREATE INDEX.","Untuk SSD, turunkan <code>random_page_cost</code> ke 1.1. Gunakan PGTune sebagai titik awal, lalu ukur. Ubah satu parameter dalam satu waktu dan catat dampaknya."],"lang":"sql","code":"CREATE EXTENSION IF NOT EXISTS pg_stat_statements;\n\nSELECT left(query, 45) AS query, calls,\n       round(total_exec_time) AS total_ms,\n       round(mean_exec_time, 2) AS rata_ms\nFROM pg_stat_statements\nORDER BY total_exec_time DESC\nLIMIT 3;\n\nALTER SYSTEM SET work_mem = '32MB';\nSELECT pg_reload_conf();","out":"                     query                     | calls  | total_ms | rata_ms\n-----------------------------------------------+--------+----------+---------\n SELECT * FROM produk WHERE kategori = $1      | 982113 |   412880 |    0.42\n SELECT sum(total) FROM pesanan WHERE dibuat > |    288 |   201517 |  699.71\n UPDATE stok SET jumlah = jumlah - $1 WHERE id |  51204 |    40963 |    0.80\n\nALTER SYSTEM\n pg_reload_conf\n----------------\n t","run":false,"tb":[{"c":"Titik awal konfigurasi server 16 GB RAM, SSD","h":["Parameter","Nilai","Catatan"],"r":[["shared_buffers","4GB","Sekitar 25% RAM, butuh restart"],["effective_cache_size","12GB","Hanya petunjuk untuk planner"],["work_mem","16MB sampai 64MB","Per operasi, dikali koneksi"],["maintenance_work_mem","1GB","VACUUM, CREATE INDEX"],["random_page_cost","1.1","SSD"],["max_connections","100 sampai 200","Pakai PgBouncer untuk lebih"]]}],"pts":["Perbaiki query dengan total waktu terbesar dulu.","shared_buffers sekitar 25% RAM.","work_mem per operasi, hati-hati dikalikan."],"q":[["Query mana yang sebaiknya dioptimasi pertama dari hasil di atas?",["SELECT produk (total 412 detik)","UPDATE stok","Tidak ada"],0,"Dipanggil hampir sejuta kali."]],"deep":{"ist":[["pg_stat_statements","Ekstensi yang mengumpulkan statistik setiap bentuk query: jumlah panggilan, total waktu, baris."],["work_mem","Memori per operasi sort/hash per query; terlalu kecil memicu temp file ke disk, terlalu besar berisiko kehabisan RAM."],["effective_cache_size","Perkiraan memori cache OS + shared_buffers untuk membantu planner memilih indeks."],["Cache hit ratio","Persentase halaman yang ditemukan di shared buffers; OLTP sehat biasanya > 99%."],["Top-N query","Daftar query dengan total waktu terbesar; tempat pertama mencari optimasi."]],"cx":[{"t":"Menemukan query paling mahal","b":"Query dengan nilai berbeda (pelanggan_id 10, 11, 12) dinormalisasi menjadi satu bentuk dengan $1, sehingga terlihat total dampaknya.","code":"CREATE TABLE pelanggan (id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY, nama text NOT NULL, kota text NOT NULL);\nCREATE TABLE pesanan (id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY, pelanggan_id bigint NOT NULL REFERENCES pelanggan,\n                      dibuat timestamptz NOT NULL, status text NOT NULL, total numeric(14,0) NOT NULL);\nINSERT INTO pelanggan (nama, kota)\nSELECT 'Pelanggan ' || g, (ARRAY['Medan','Bandung','Surabaya','Makassar','Denpasar'])[1 + g % 5] FROM generate_series(1, 20000) g;\nINSERT INTO pesanan (pelanggan_id, dibuat, status, total)\nSELECT 1 + (g::bigint * 7919) % 20000, timestamptz '2026-01-01 00:00+07' + (g % 320) * interval '1 day' + (g % 86400) * interval '1 second',\n       (ARRAY['baru','dibayar','dikirim','selesai','batal'])[1 + g % 5], 10000 + (g::bigint * 37) % 2000000\nFROM generate_series(1, 300000) g;\nANALYZE;\nCREATE EXTENSION IF NOT EXISTS pg_stat_statements;\nSELECT pg_stat_statements_reset() IS NOT NULL AS reset;\n\nSELECT count(*) FROM pesanan WHERE pelanggan_id = 10;\nSELECT count(*) FROM pesanan WHERE pelanggan_id = 11;\nSELECT count(*) FROM pesanan WHERE pelanggan_id = 12;\nSELECT status, sum(total) FROM pesanan GROUP BY status;\nSELECT * FROM pelanggan WHERE id = 5;\n\nSELECT calls, rows, left(regexp_replace(query, '\\s+', ' ', 'g'), 60) AS query\nFROM pg_stat_statements\nWHERE query NOT ILIKE '%pg_stat_statements%' AND query ILIKE 'select%'\nORDER BY total_exec_time DESC LIMIT 4;","lang":"sql","out":" reset\n-------\n t\n(1 row)\n\n count\n-------\n    15\n(1 row)\n\n count\n-------\n    15\n(1 row)\n\n count\n-------\n    15\n(1 row)\n\n status  |     sum\n---------+-------------\n baru    | 57925550000\n batal   | 57925330000\n dibayar | 57924670000\n dikirim | 57924890000\n selesai | 57925110000\n(5 rows)\n\n id |    nama     | kota\n----+-------------+-------\n  5 | Pelanggan 5 | Medan\n(1 row)\n\n calls | rows |                         query\n-------+------+--------------------------------------------------------\n     3 |    3 | SELECT count(*) FROM pesanan WHERE pelanggan_id = $1\n     1 |    5 | SELECT status, sum(total) FROM pesanan GROUP BY status\n     1 |    1 | SELECT * FROM pelanggan WHERE id = $1\n(3 rows)"},{"t":"work_mem terlalu kecil memaksa sort ke disk","b":"\"external merge Disk\" berarti sort tumpah ke disk. Naikkan work_mem per sesi atau per role laporan, bukan global, karena dikalikan jumlah koneksi.","code":"CREATE TABLE pelanggan (id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY, nama text NOT NULL, kota text NOT NULL);\nCREATE TABLE pesanan (id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY, pelanggan_id bigint NOT NULL REFERENCES pelanggan,\n                      dibuat timestamptz NOT NULL, status text NOT NULL, total numeric(14,0) NOT NULL);\nINSERT INTO pelanggan (nama, kota)\nSELECT 'Pelanggan ' || g, (ARRAY['Medan','Bandung','Surabaya','Makassar','Denpasar'])[1 + g % 5] FROM generate_series(1, 20000) g;\nINSERT INTO pesanan (pelanggan_id, dibuat, status, total)\nSELECT 1 + (g::bigint * 7919) % 20000, timestamptz '2026-01-01 00:00+07' + (g % 320) * interval '1 day' + (g % 86400) * interval '1 second',\n       (ARRAY['baru','dibayar','dikirim','selesai','batal'])[1 + g % 5], 10000 + (g::bigint * 37) % 2000000\nFROM generate_series(1, 300000) g;\nANALYZE;\nSET work_mem = '256kB';\nEXPLAIN (ANALYZE, COSTS OFF, TIMING OFF, SUMMARY OFF) SELECT * FROM pesanan ORDER BY total DESC LIMIT 100000;\nSET work_mem = '64MB';\nEXPLAIN (ANALYZE, COSTS OFF, TIMING OFF, SUMMARY OFF) SELECT * FROM pesanan ORDER BY total DESC LIMIT 100000;","lang":"sql","out":"                                 QUERY PLAN\n-----------------------------------------------------------------------------\n Limit (actual rows=100000 loops=1)\n   ->  Gather Merge (actual rows=100000 loops=1)\n         Workers Planned: 1\n         Workers Launched: 1\n         ->  Sort (actual rows=50415 loops=2)\n               Sort Key: total DESC\n               Sort Method: external merge  Disk: 7096kB\n               Worker 0:  Sort Method: external merge  Disk: 7056kB\n               ->  Parallel Seq Scan on pesanan (actual rows=150000 loops=2)\n(9 rows)\n\n                                 QUERY PLAN\n-----------------------------------------------------------------------------\n Limit (actual rows=100000 loops=1)\n   ->  Gather Merge (actual rows=100000 loops=1)\n         Workers Planned: 1\n         Workers Launched: 1\n         ->  Sort (actual rows=50440 loops=2)\n               Sort Key: total DESC\n               Sort Method: quicksort  Memory: 17485kB\n               Worker 0:  Sort Method: quicksort  Memory: 15898kB\n               ->  Parallel Seq Scan on pesanan (actual rows=150000 loops=2)\n(9 rows)"}]}},{"b":["<b>Backup logis</b> dengan <code>pg_dump</code> menghasilkan perintah SQL atau format arsip untuk satu database. Fleksibel (bisa memulihkan satu tabel, pindah versi PostgreSQL), tetapi lambat untuk database ratusan GB. <code>pg_dumpall</code> menyertakan role dan tablespace.","<b>Backup fisik</b> dengan <code>pg_basebackup</code> menyalin seluruh direktori data. Cepat dipulihkan dan, jika digabung dengan arsip WAL, memungkinkan <b>Point-in-Time Recovery (PITR)</b>: memulihkan ke detik tertentu, misalnya tepat sebelum seseorang tidak sengaja menjalankan <code>DELETE</code> tanpa WHERE.","Di produksi, pakai alat seperti <b>pgBackRest</b> atau <b>Barman</b> untuk backup terjadwal, kompresi, enkripsi, dan penyimpanan di object storage. Ingat aturan 3-2-1 dan yang paling penting: <b>uji restore secara rutin</b>."],"lang":"bash","code":"# backup logis format custom (terkompresi, bisa restore sebagian)\npg_dump -h localhost -U postgres -Fc -f tokodb_2026-11-05.dump tokodb\n\n# restore hanya tabel produk ke database uji\npg_restore -U postgres -d tokodb_uji -t produk tokodb_2026-11-05.dump\n\n# backup fisik + WAL untuk PITR\npg_basebackup -h db1 -U replikator -D /backup/base -Ft -z -X stream -P","out":"pg_basebackup: initiating base backup, waiting for checkpoint to complete\npg_basebackup: checkpoint completed\n2147483/2147483 kB (100%), 1/1 tablespace\npg_basebackup: base backup completed","run":false,"tb":[{"c":"Perbandingan backup","h":["Aspek","pg_dump (logis)","pg_basebackup (fisik)"],"r":[["Cakupan","Satu database","Seluruh cluster"],["Restore sebagian","Bisa (per tabel)","Tidak"],["Lintas versi","Bisa","Tidak"],["Kecepatan untuk data besar","Lambat","Cepat"],["PITR","Tidak","Bisa dengan arsip WAL"]]}],"so":[{"q":"Tulis perintah pg_dump yang hanya mencadangkan schema <code>penjualan</code> dari database tokodb dalam format custom.","h":"Opsi -n untuk schema, -Fc untuk format custom.","a":"pg_dump -U postgres -Fc -n penjualan -f penjualan.dump tokodb","lang":"sql"}],"pts":["pg_dump untuk fleksibilitas, pg_basebackup untuk kecepatan dan PITR.","pgBackRest atau Barman untuk produksi.","Backup yang tidak pernah diuji restore belum terbukti."],"q":[["Data terhapus pukul 14.03. Cara memulihkan ke 14.02?",["PITR dari base backup + arsip WAL","pg_dump semalam","VACUUM"],0,"recovery_target_time."]],"deep":{"ist":[["Backup logis","pg_dump/pg_dumpall menghasilkan SQL atau format custom; fleksibel, lambat untuk database besar."],["Backup fisik","Salinan berkas data + WAL (pg_basebackup, pgBackRest, Barman); cepat dipulihkan."],["PITR","Point-In-Time Recovery: pulihkan ke detik tertentu memakai base backup + arsip WAL."],["Aturan 3-2-1","3 salinan, 2 media berbeda, 1 di luar lokasi; ditambah uji restore berkala."],["Restore drill","Latihan restore terjadwal; backup yang tidak pernah diuji dianggap tidak ada."]],"cx":[{"t":"Backup logis dan fisik di dunia kerja","code":"# Logis: satu database, format custom (bisa restore sebagian tabel, paralel)\npg_dump -h db.internal -U backup -d toko -Fc -Z 6 -f toko_$(date +%F).dump\npg_restore -l toko_2026-11-19.dump | grep pesanan          # lihat isi\npg_restore -d toko_uji -j 4 --no-owner toko_2026-11-19.dump  # restore paralel ke database uji\n\n# Fisik + PITR dengan pgBackRest (pgbackrest.conf: repo1 di S3, retensi 4 full)\npgbackrest --stanza=toko --type=full backup                 # Minggu 01.00\npgbackrest --stanza=toko --type=diff backup                 # Senin-Sabtu 01.00\n# archive_command = 'pgbackrest --stanza=toko archive-push %p'   (WAL dikirim terus menerus)\n\n# Insiden: tabel terhapus pukul 14:32:10 -> pulihkan ke 14:32:00 di server baru\npgbackrest --stanza=toko --type=time --target=\"2026-11-19 14:32:00+07\" --target-action=promote restore","lang":"bash"},{"t":"Memeriksa kesiapan PITR dari dalam database","b":"Di cluster latihan archive_mode masih off, artinya belum bisa PITR. Di produksi, failed_count yang naik harus memicu alert.","code":"SELECT name, setting FROM pg_settings\nWHERE name IN ('wal_level', 'archive_mode', 'archive_command', 'max_wal_senders', 'full_page_writes') ORDER BY name;\nSELECT archived_count, failed_count, last_archived_time IS NOT NULL AS pernah_mengarsip FROM pg_stat_archiver;","lang":"sql","out":"       name       |  setting\n------------------+------------\n archive_command  | (disabled)\n archive_mode     | off\n full_page_writes | on\n max_wal_senders  | 10\n wal_level        | replica\n(5 rows)\n\n archived_count | failed_count | pernah_mengarsip\n----------------+--------------+------------------\n              0 |            0 | f\n(1 row)"}]}},{"b":["<b>Streaming replication</b> mengirim WAL dari server <b>primary</b> ke satu atau lebih <b>standby</b> secara terus-menerus. Standby bisa melayani query baca (hot standby) dan siap dipromosikan jika primary mati. Mode <b>asinkron</b> cepat tetapi bisa kehilangan beberapa transaksi terakhir; mode <b>sinkron</b> menunggu standby mengonfirmasi.","<b>Logical replication</b> mereplikasi perubahan per tabel lewat publication dan subscription. Cocok untuk upgrade versi utama dengan downtime minimal atau mengirim sebagian tabel ke sistem lain.","<b>High availability</b> butuh otomatisasi failover: <b>Patroni</b> (dengan etcd atau Consul) adalah standar industri, sering dipadukan dengan HAProxy atau PgBouncer. Di Kubernetes, operator seperti CloudNativePG mengurus semuanya."],"lang":"sql","code":"-- di primary: pantau standby\nSELECT client_addr, state, sync_state,\n       pg_wal_lsn_diff(pg_current_wal_lsn(), replay_lsn) AS tertinggal_byte\nFROM pg_stat_replication;\n\n-- logical replication satu tabel\nCREATE PUBLICATION pub_produk FOR TABLE produk;\n-- di server tujuan:\nCREATE SUBSCRIPTION sub_produk\n  CONNECTION 'host=db1 dbname=tokodb user=replikator'\n  PUBLICATION pub_produk;","out":" client_addr |   state   | sync_state | tertinggal_byte\n-------------+-----------+------------+-----------------\n 10.0.1.12   | streaming | async      |             328\n 10.0.1.13   | streaming | async      |               0\n\nCREATE PUBLICATION\nCREATE SUBSCRIPTION","run":false,"pts":["Streaming replication: WAL ke standby.","Logical replication: per tabel, lintas versi.","Patroni untuk failover otomatis."],"q":[["Risiko replikasi asinkron saat primary mati mendadak?",["Beberapa transaksi terakhir bisa hilang","Standby tidak bisa dibaca","Tidak ada risiko"],0,"Standby sedikit tertinggal."]],"deep":{"ist":[["Streaming replication","Standby menerima WAL dari primary secara terus menerus dan bisa dipakai untuk baca (hot standby)."],["Synchronous vs asynchronous","Sync menunggu standby mengonfirmasi (RPO 0, lebih lambat); async lebih cepat dengan risiko kehilangan beberapa detik data."],["Replication slot","Menjamin WAL tidak dihapus sebelum diterima standby; slot yang macet bisa memenuhi disk."],["Failover / switchover","Mempromosikan standby menjadi primary saat primary mati / secara terencana untuk pemeliharaan."],["Patroni","Pengelola HA populer yang memakai etcd/Consul untuk memilih leader dan failover otomatis."],["Logical replication","Replikasi per tabel (publication/subscription); dipakai untuk upgrade versi besar dan CDC."]],"cx":[{"t":"Arsitektur HA 3 node dengan Patroni","code":"# patroni.yml (potongan)\nscope: toko-prod\netcd3: { hosts: etcd-1:2379,etcd-2:2379,etcd-3:2379 }\nbootstrap:\n  dcs:\n    ttl: 30\n    maximum_lag_on_failover: 1048576            # standby tertinggal > 1 MB tidak boleh jadi primary\n    synchronous_mode: true                      # minimal 1 standby sinkron -> RPO 0\n    postgresql:\n      parameters: { wal_level: replica, hot_standby: \"on\", max_wal_senders: 10, max_replication_slots: 10 }\n\n# Aplikasi terhubung ke HAProxy/PgBouncer:\n#   :5432 -> primary (cek REST Patroni GET /primary)\n#   :5433 -> replika baca (GET /replica)\n# Switchover terencana: patronictl switchover --candidate db-2 --force","lang":"yaml"},{"t":"Query pemantauan replikasi yang dijalankan di primary","b":"Di cluster latihan tidak ada standby sehingga hasilnya kosong. Di produksi, alert jika lag > 100 MB atau slot tidak aktif menahan WAL.","code":"SELECT application_name, state, sync_state,\n       pg_size_pretty(pg_wal_lsn_diff(pg_current_wal_lsn(), replay_lsn)) AS lag\nFROM pg_stat_replication;\n\nSELECT slot_name, active,\n       pg_size_pretty(pg_wal_lsn_diff(pg_current_wal_lsn(), restart_lsn)) AS wal_ditahan\nFROM pg_replication_slots;\n\nSELECT pg_is_in_recovery() AS ini_standby;","lang":"sql","out":" application_name | state | sync_state | lag\n------------------+-------+------------+-----\n(0 rows)\n\n slot_name | active | wal_ditahan\n-----------+--------+-------------\n(0 rows)\n\n ini_standby\n-------------\n f\n(1 row)"}]}},{"b":["Pantau metrik ini: jumlah koneksi dibanding <code>max_connections</code>, <b>cache hit ratio</b> (idealnya di atas 99% untuk OLTP), query lambat, transaksi yang <b>idle in transaction</b> terlalu lama (menahan VACUUM), lag replikasi, ukuran database, dan umur wraparound.","Aktifkan <code>log_min_duration_statement</code> (misalnya 500 ms) untuk mencatat query lambat dan analisis dengan <b>pgBadger</b>. Untuk dasbor, pakai <b>postgres_exporter</b> + Prometheus + Grafana, atau layanan seperti pganalyze.","Atur peringatan sebelum masalah terjadi: disk di atas 80%, lag replikasi di atas 1 menit, koneksi di atas 80% batas, dan backup terakhir lebih dari 24 jam."],"lang":"sql","code":"SELECT round(100.0 * sum(blks_hit) / nullif(sum(blks_hit + blks_read), 0), 2) AS cache_hit_persen\nFROM pg_stat_database;\n\nSELECT pid, now() - xact_start AS lama, state\nFROM pg_stat_activity\nWHERE state = 'idle in transaction'\n  AND now() - xact_start > interval '5 minutes';\n\nSELECT pg_size_pretty(pg_database_size('tokodb')) AS ukuran;","out":" cache_hit_persen\n------------------\n            99.42\n\n pid  |      lama       |        state\n------+-----------------+---------------------\n 5120 | 00:17:03.912    | idle in transaction\n\n ukuran\n--------\n 38 GB","run":false,"tb":[{"c":"Checklist DBA","h":["Frekuensi","Pemeriksaan"],"r":[["Harian","Backup berhasil, lag replikasi, disk, query lambat, koneksi idle in transaction"],["Mingguan","Pertumbuhan tabel, bloat, indeks tak terpakai, log error"],["Bulanan","Uji restore, tinjau role dan hak akses, rencana kapasitas"],["Tahunan","Upgrade versi utama, latihan failover, tinjau konfigurasi"]]}],"so":[{"q":"Tampilkan 5 tabel terbesar beserta ukurannya (termasuk indeks) dalam format mudah dibaca.","h":"pg_total_relation_size dan pg_size_pretty dari pg_stat_user_tables.","a":"SELECT relname, pg_size_pretty(pg_total_relation_size(relid)) AS ukuran\nFROM pg_stat_user_tables\nORDER BY pg_total_relation_size(relid) DESC\nLIMIT 5;","lang":"sql"}],"pts":["Cache hit ratio di atas 99% untuk OLTP.","Idle in transaction menahan VACUUM.","Prometheus + Grafana atau pgBadger."],"q":[["Kenapa sesi \"idle in transaction\" berbahaya?",["Menahan lock dan mencegah VACUUM membersihkan baris mati","Memakai CPU 100%","Menghapus data"],0,"Snapshot lama tetap dipertahankan."]],"deep":{"ist":[["pg_stat_activity","Daftar sesi aktif: query yang berjalan, status, berapa lama, dan apa yang ditunggu (wait_event)."],["Idle in transaction","Sesi membuka transaksi lalu diam; menahan kunci dan menghambat VACUUM."],["Observability stack","postgres_exporter + Prometheus + Grafana, atau layanan seperti pganalyze, Datadog, CloudWatch."],["Capacity planning","Memperkirakan kebutuhan disk, CPU, koneksi beberapa bulan ke depan dari tren pertumbuhan."],["Alert fatigue","Terlalu banyak alert tidak penting sehingga yang penting terabaikan; alert harus bisa ditindaklanjuti."]],"cx":[{"t":"Query checklist pagi DBA","b":"Checklist lengkap juga mencakup: hasil backup semalam, lag replikasi, ruang disk, error di log, dan usia transaksi tertua.","code":"CREATE TABLE pelanggan (id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY, nama text NOT NULL, kota text NOT NULL);\nCREATE TABLE pesanan (id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY, pelanggan_id bigint NOT NULL REFERENCES pelanggan,\n                      dibuat timestamptz NOT NULL, status text NOT NULL, total numeric(14,0) NOT NULL);\nINSERT INTO pelanggan (nama, kota)\nSELECT 'Pelanggan ' || g, (ARRAY['Medan','Bandung','Surabaya','Makassar','Denpasar'])[1 + g % 5] FROM generate_series(1, 20000) g;\nINSERT INTO pesanan (pelanggan_id, dibuat, status, total)\nSELECT 1 + (g::bigint * 7919) % 20000, timestamptz '2026-01-01 00:00+07' + (g % 320) * interval '1 day' + (g % 86400) * interval '1 second',\n       (ARRAY['baru','dibayar','dikirim','selesai','batal'])[1 + g % 5], 10000 + (g::bigint * 37) % 2000000\nFROM generate_series(1, 300000) g;\nANALYZE;\nSELECT round(100.0 * sum(blks_hit) / nullif(sum(blks_hit) + sum(blks_read), 0), 2) AS cache_hit_pct\nFROM pg_stat_database WHERE datname = current_database();\n\nSELECT relname AS tabel, pg_size_pretty(pg_total_relation_size(relid)) AS total_dengan_indeks,\n       n_live_tup AS baris_hidup, n_dead_tup AS baris_mati\nFROM pg_stat_user_tables ORDER BY pg_total_relation_size(relid) DESC;\n\nSELECT state, count(*) FROM pg_stat_activity WHERE backend_type = 'client backend' GROUP BY state;\n\nSELECT pid, now() - xact_start AS lama, state, left(query, 40) AS query\nFROM pg_stat_activity\nWHERE xact_start < now() - interval '5 minutes' AND backend_type = 'client backend';","lang":"sql","out":" cache_hit_pct\n---------------\n        100.00\n(1 row)\n\n   tabel   | total_dengan_indeks | baris_hidup | baris_mati\n-----------+---------------------+-------------+------------\n pesanan   | 26 MB               |      300000 |          0\n pelanggan | 1712 kB             |       20000 |          0\n(2 rows)\n\n state  | count\n--------+-------\n active |     1\n(1 row)\n\n pid | lama | state | query\n-----+------+-------+-------\n(0 rows)"},{"t":"Aturan alert Prometheus untuk PostgreSQL","code":"groups:\n- name: postgresql\n  rules:\n  - alert: PostgresReplikasiTertinggal\n    expr: pg_replication_lag_seconds > 30\n    for: 5m\n    labels: { severity: page }\n  - alert: PostgresKoneksiHampirPenuh\n    expr: sum(pg_stat_activity_count) / pg_settings_max_connections > 0.85\n    for: 10m\n    labels: { severity: warning }\n  - alert: PostgresTransaksiIdleLama\n    expr: pg_stat_activity_max_tx_duration{state=\"idle in transaction\"} > 300\n    labels: { severity: warning }\n  - alert: PostgresBackupGagal\n    expr: time() - pgbackrest_backup_last_full_time > 8 * 86400\n    labels: { severity: page }","lang":"yaml"}]}}]);
